COLLDATA("tadabburar","ar",[[224,"§هود\nwords\nمُعجِزِينَفَائِتِينَ مِن عَذَابِ اللهِ بِالهَرَبِ.\nوَأَخبَتُواخَضَعُوا لِلهِ.\nأَرَاذِلُنَاأَسَافِلُنَا.\nبَادِيَ الرَّأيِمِن غَيرِ تَفَكُّرٍ، وَلاَ رَوِيَّةٍ.\nفَعُمِّيَت عَلَيكُمفَأُخفِيَت عَلَيكُم.\nأَنُلزِمُكُمُوهَاأَنُجبِرُكم عَلَى قَبُولِهَا.\ndeeds\nصلِّ ركعتين، ثم ادع الله تعالى وتضرع إليه أن يرزقك الإخبات إليه؛ أي: التواضع والتسليم له سبحانه.\nأرسل رسالة تقترح فيها ثلاث وسائل لهداية الوجهاء ودعوتهم.\nألق كلمة، أو ابذل نصيحة، أو غير منكرًا بالأسلوب الحسن، ثم اقرأ قصص الأنبياء في سورة هود؛ فسيظهر لك من مقاصدها الشيءُ الكثير.\nguid\nإضلال الآخرين سبب في مضاعفة العذاب؛ فإياك أن تدل غيرك على معصية.\nلا تحتقر أحدًا في دعوتك لمكانته الاجتماعية أو المادية.\nاعتنِ أكثر بهداية الوجهاء؛ فإنهم سبب لهداية أتباعهم.\nrefl\nيُضَٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُواْ يَسۡتَطِيعُونَ ٱلسَّمۡعَ وَمَا كَانُواْ يُبۡصِرُونَ ٢٠\n﴿يُضَٰعَفُ لَهُمُ ٱلۡعَذَابُۚ﴾... لأنهم ضلوا بأنفسهم، وأضلوا غيرهم. السعدي:٣٧٩.\nلماذا يضاعف لهم العذاب؟\nلَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ ٢٢\nيخبر تعالى عن حالهم أنهم أخسر الناس صفقة في الدار الآخرة؛ لأنهم استبدلوا الدركات عن الدرجات، واعتاضوا عن نعيم الجنان بحميم آن، وعن شرب الرحيق المختوم بسموم وحميم وظل من يحموم، وعن الحور العين بطعام من غسلين، وعن القصور العالية بالهاوية، وعن قرب الرحمن ورؤيته بغضب الديان وعقوبته. ابن كثير:٢/٤٢٣.\nلمَ وصفهم الله تعالى بالأخسرين، ولم يصفهم بالخاسرين؟\nإِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَأَخۡبَتُوٓاْ إِلَىٰ رَبِّهِمۡ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ ٢٣\n﴿وَأَخۡبَتُوٓاْ إِلَىٰ رَبِّهِمۡ﴾: الإخبات الخشوع للمخافة الثابتة في القلب، وأصل الإخبات الاستواء؛ من الخبت وهو الأرض المستوية الواسعة؛ فالإخبات: الخشوع والاطمئنان، أو الإنابة إلى الله -عز وجل- المستمرة. القرطبي:١١/٩٦.\nكيف يكون العبد من المخبتين؟\nفَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۢ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ ٢٧\nقال علماؤنا: إنَّما كان ذلك لاستيلاء الرياسة على الأشراف، وصعوبة الانفكاك عنها، والأنفة من الانقياد للغير. والفقير خلي عن تلك الموانع؛ فهو سريع إلى الإجابة والانقياد، وهذا غالب أحوال أهل الدنيا. القرطبي:١١/٩٩.\nلماذا يقبل الحق أهل الفقر والمسكنة، ويرده أهل الرياسة والغنى غالبًا؟\nفَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ\nوكان هذا جهلًا منهم؛ لأنهم عابوا نبي الله -صلى الله عليه وسلم- بما لا عيب فيه؛ لأن الأنبياء -صلوات الله وسلامه عليهم- إنَّما عليهم أن يأتوا بالبراهين والآيات، وليس عليهم تغيير الصور والهيئات، وهم يرسلون إلى الناس جميعًا، فإذا أسلم منهم الدنيء لم يلحقهم من ذلك نقصان؛ لأن عليهم أن يقبلوا إسلام كل من أسلم منهم. القرطبي:١١/٩٩.\nهل اتباع الضعفاء والفقراء للداعية عيب ونقص في دعوته؟\nفَقَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرٗا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِينَ هُمۡ أَرَاذِلُنَا بَادِيَ ٱلرَّأۡيِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِن فَضۡلِۢ بَلۡ نَظُنُّكُمۡ كَٰذِبِينَ ٢٧\n(أراذلنا): جمع أرذل، وهم سفلة الناس؛ وإنَّما وصفوهم بذلك لفقرهم، جهلًا منهم واعتقادًا أن الشرف هو بالمال والجاه، وليس الأمر كما اعتقدوا؛ بل المؤمنون كانوا أشرف منهم على حال فقرهم وخمولهم في الدنيا. ﴿بَادِيَ ٱلرَّأۡيِ﴾ أي: أول الرأي من غير نظر ولا تدبير، والمعنى: اتبعك الأراذل من غير نظر، ولا تثبت. ابن جزي:١/٣٩٤.\nبينت هذه الآية معالم أهل الكفر في رميهم بالتهم لأهل الحق، وضحها.\nقَالَ يَٰقَوۡمِ أَرَءَيۡتُمۡ إِن كُنتُ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّي وَءَاتَىٰنِي رَحۡمَةٗ مِّنۡ عِندِهِۦ فَعُمِّيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَٰرِهُونَ ٢٨\nوهذا تعريض بأنهم لو تأملوا تأملًّا بريئًا من الكراهية والعداوة لعلموا صدق دعوته. ابن عاشور:١٢/٥١.\nللعناد والكراهية أثر في مواقف المشركين والمعاندين، وضح ذلك."],[225,"§هود\nwords\nتَزدَرِيتَحتَقِرُ.\nأَم يَقُولُونَبَل أَيَقُولُونَ.\nافتَرَاهُاِختَلَقَهُ.\nفَلا تَبتَئِسلا تَحزَن.\nالفُلكَالسَّفِينَةَ.\nبِأَعيُنِنَابِحِفظِنَا وَمَرأًى مِنَّا.\ndeeds\nاحتسب في تعليم مسلم حفظ قصار السور.\nتعاون مع مؤسسة خيرية في عمل خير من غير أن تطلب أجرًا على ذلك.\nزُر أحد الضعفاء الصالحين، وقدّم له هدية.\nguid\nللدعوة إلى الله مبادئ وثوابت لا يمكن التنازل عنها مهما تساهلنا مع الخصوم.\nمن أسباب النصر والرزق والحفظ: العناية بالضعفاء؛ فحتى الأنبياء لو وقعوا في ظلم الضعفاء لم يأمنوا من عقوبة الله سبحانه، فكيف بغيرهم؟!\nالعذاب إذا نزل بالأمم المكذبة فلن يقدر أحد على دفعه ورفعه.\nrefl\nوَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ إِنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ٢٩\n﴿وَمَآ أَنَا۠ بِطَارِدِ ٱلَّذِينَ ءَامَنُوٓاْۚ﴾: هذا دليل على أنهم طلبوا منه طرد المؤمنين. ﴿أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ﴾ أي: صائرون إلى ربهم في المعاد، فيجزي مَن طردهم. القرطبي:٢/٣٩٧.\nمن علامات صدق الداعية استهدافه لجميع طبقات المجتمع، وضح ذلك من خلال الآية.\nوَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ\nأي: من يمنعني من عذابه؛ فإنَّ طردهم موجب للعذاب والنكال الذي لا يمنعه من دون الله مانع. السعدي:٣٨١.\nليس للداعية الحق في استبعاد الفقراء من دعوته، وضح ذلك.\nوَيَٰقَوۡمِ مَن يَنصُرُنِي مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ ٣٠\nأي: مَن يخلصني؛ أي: ينجيني ﴿مِّنَ ٱللَّهِۚ﴾ أي: من عقابه؛ لأن طردهم إهانة تؤذيهم بلا موجب معتبر عند الله، والله لا يحب إهانة أوليائه. ابن عاشور:١٢/٥٦.\nإهانة أولياء الله تعالى عظيمة عنده -وإن كانوا من الضعفاء- بين ذلك.\nقَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ٣٢\nالجدل في الدين محمود؛ ولهذا جادل نوح والأنبياء قومهم حتى يظهر الحق؛ فمن قبله أنجح وأفلح، ومن رده خاب وخسر، وأمَّا الجدال لغير الحق حتى يظهر الباطل في صورة الحق فمذموم، وصاحبه في الدارين ملوم. القرطبي:١١/١٠٥.\nبيِّن الجدال المذموم.\nقَالُواْ يَٰنُوحُ قَدۡ جَٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ٣٢\nومن الجدال ما هو محمود؛ وذلك إذا كان مع كافر حربي في منعته، ويطمع في الجدال أن يهتدي؛ ومن ذلك هذه الآية، ومنه قوله تعالى: ﴿وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُ﴾ [النحل: ١٢٥] إلى غير ذلك من الأمثلة. ومن الجدال ما هو مكروه؛ وهو ما يقع بين المسلمين بعضهم في بعض في طلب علل الشرائع، وتصور ما يخبر الشرع به من قدرة الله. وقد نهى النبي -صلى الله عليه وسلم- عن ذلك، وكرهه العلماء، والله المستعان. ابن عطية:٣/١٦٦.\nبيِّن الجدال المحمود.\nقَاَلَ إنِّمَا يَأتِيكُم به إن شَاءَ ومَا أَنتُم بمُعجِزِينَ\n﴿وَمَآ أَنتُم بِمُعۡجِزِينَ﴾ أي: بفائتين، وقيل: بغالبين بكثرتكم؛ لأنهم أعجبوا بذلك؛ كانوا ملأوا الأرض سهلًا وجبلًا. القرطبي:١١/١٠٦.\nهل ينتفع المدعو بالنصح إذا كتب الله تعالى عليه الغواية؟\nفَلَا تَبۡتَئِسۡ بِمَا كَانُواْ يَفۡعَلُونَ ٣٦\nأي: لا تحزن؛ فإني مهلكهم ومنقذك منهم، فحينئذ دعا نوح عليهم. البغوي:٢/٣٩٨.\nمتى دعا نوح -عليه السلام- على قومه؟ وماذا تفيد من ذلك؟"],[226,"§هود\nwords\nوَفَارَنَبَعَ المَاءُ بِقُوَّةٍ.\nالتَّنُّورُ المَكَانُ الَّذِي يُخبَزُ فِيهِ.\nمَجرَاهَاجَريُهَا.\nوَمُرسَاهَامُنتَهَى سَيرِهَا وَرَسوِهَا.\nأَقلِعِيأَمسِكِي عَنِ المَطَرِ.\ndeeds\nأرسل رسالة تحذر فيها من السخرية بالعلماء؛ فإنهم ورثة الأنبياء.\nحافظ على دعاء الركوب هذا اليوم.\nانصح شخصًا محتاجًا للنصيحة؛ كما فعل نوح -عليه السلام- مع ابنه.\nguid\nالقرابة والنسب لا تنفعان من لم يؤمن بالله سبحانه.\nلا تبتئس إذا قَلَّ من يسمع نصحك، أو كَثُرَ مخالفوك؛ فإنَّ الأنبياء قبلك قد أفنوا أعمارهم الطويلة في الدعوة، ولم يستجب لبعضهم إلا القليل.\nالأسباب الدنيوية مهما عظمت لا تنفع العاصي إذا أراد الله عقوبته.\nrefl\nوَيَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَأٞ مِّن قَوۡمِهِۦ سَخِرُواْ مِنۡهُۚ قَالَ إِن تَسۡخَرُواْ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ ٣٨\nجعل قومه يمرون به وهو في عمله، ويسخرون منه، ويقولون: يا نوح، لقد صرت نجارًا بعد النبوة؟! البغوي:٢/٣٩٩.\nعلو منزلة الصالحين لم تمنع الجاهلين من الاستهزاء بهم، وضح ذلك.\nقُلۡنَا ٱحۡمِلۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ\nأي: من كل صنف من أصناف المخلوقات ذكر وأنثى؛ لتبقى مادة سائر الأجناس. السعدي:٣٨٢.\nلماذا أمر الله نوحًا أن يحمل معه في السفينة من كل زوجين اثنين؟\nوَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٞ ٤٠\nوجملة ﴿وَمَآ ءَامَنَ مَعَهُۥٓ إِلَّا قَلِيلٌ﴾ اعتراض لتكميل الفائدة من القصة في قلة الصالحين. ابن عاشور:١٢/٧٣.\nالصالحون قليل في أقوامهم في الغالب، دلل لذلك.\nوَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡرٜىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ ٤١\nوفي هذه الآية دليل على ذكر البسملة عند ابتداء كل فعل. القرطبي:١١/١٢١.\nما الفائدة العملية من الآية؟\nوَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡرٜىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ ٤١\nالتعليل بالمغفرة والرحمة رمز إلى أن الله وعَده بنجاتهم؛ وذلك من غفرانه ورحمته. ابن عاشور:١٢/٧٤.\nما فائدة التعليل بالمغفرة والرحمة في الآية الكريمة؟\nقَالَ سَـَٔاوِيٓ إِلَىٰ جَبَلٖ يَعۡصِمُنِي مِنَ ٱلۡمَآءِۚ قَالَ لَا عَاصِمَ ٱلۡيَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ\nفلا يعصم أحدًا جبلٌ ولا غيره، ولو تسبب بغاية ما يمكنه من الأسباب لما نجا إن لم ينجه الله. السعدي:٣٨٢.\nفي حالة الشدائد هل نتعلق بالأسباب أم بالمسبب؛ وهو الله سبحانه؟\nوَنَادَىٰ نُوحٞ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَٰكِمِينَ ٤٥ قَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ\n﴿فَقَالَ رَبِّ إِنَّ ٱبۡنِي مِنۡ أَهۡلِي﴾ أي: وقد وعدتني بنجاة أهلي، ووعدك الحق الذي لا يخلف، فكيف غرق وأنت أحكم الحاكمين؟! (قال يا نوح إنه ليس من أهلك) أي: الذين وعدت إنجاءهم؛ لأني إنَّما وعدتك بنجاة من آمن من أهلك؛ ولهذا قال: ﴿وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ﴾، فكان هذا الولد ممن سبق عليه القول بالغرق لكفره ومخالفته أباه نبي الله نوحًا -عليه السلام-. ابن كثير:٢/٤٢٩.\nالإسلام والإيمان شرط لانتفاع الأقارب بعضهم من بعض في الآخرة، وضح ذلك."],[227,"§هود\nwords\nأَعِظُكَ أَن تَكُونَأَعِظُكَ لِئَلاَّ تَكُونَ.\nأَعُوذُ بِكَأَستَجِيرُ بِكَ.\nمُفتَرُونَكَاذِبُونَ.\nمِدرَارًامُتَتَابِعًا كَثِيرًا.\nعَن قَولِكَمِن أَجلِ قَولِكَ.\ndeeds\nراجع أدعيتك التي اعتدت عليها تحسبًا أن يكون فيها خطأ.\nاقرأ قصة نوح -عليه السلام-، واستخرج منها ثلاث فوائد.\nاستغفر الله سبعين مرة.\nguid\nلا تحزن من عدم إجابة دعاء الله لك في بعض مطالبك الدنيوية؛ فقد يكون منعك إياها خير لك.\nالصبر والتقوى هما سببا الانتصار على من ظلمك.\nموعود الله سبحانه يأتي غالبًا في أواخر الأمور؛ بعد أن يتحقق الاختبار والابتلاء.\nrefl\nقَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ\nقال الجمهور: ليس من أهل دينك، ولا ولايتك، فهو على حذف مضاف، وهذا يدل على أن حكم الاتفاق في الدين أقوى من حكم النسب. القرطبي ١١/١٣٤.\nما الأصل العظيم الذي نتعلمه من هذه الآية المباركة ؟\nقَالَ يَٰنُوحُ إِنَّهُۥ لَيۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَيۡرُ صَٰلِحٖۖ فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ\n﴿فَلَا تَسۡـَٔلۡنِ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۖ﴾ أي: ما لا تعلم عاقبته ومآله، وهل يكون خيرًا أو غير خير. السعدي:٣٨٢.\nقد يدعو الإنسان بشيء، ويكون الخير في عدم الاستجابة، بَيِّن ذلك من خلال الآية.\nوَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ ٤٧\nفبالمغفرة والرحمة ينجو العبد من أن يكون من الخاسرين. السعدي:٣٨٣.\nما أسباب النجاة من الخسارة في الآخرة؟\nوَإِلَّا تَغۡفِرۡ لِي وَتَرۡحَمۡنِيٓ أَكُن مِّنَ ٱلۡخَٰسِرِينَ ٤٧\nطلب المغفرة ابتداء... ثم أعقبها بطلب الرحمة؛ لأنّه إذا كان بمحل الرضى من الله كان أهلًا للرحمة. ابن عاشور:١٢/٨٨.\nلماذا قدم طلب المغفرة على طلب الرحمة؟\nقِيلَ يَٰنُوحُ ٱهۡبِطۡ بِسَلَٰمٖ مِّنَّا وَبَرَكَٰتٍ عَلَيۡكَ وَعَلَىٰٓ أُمَمٖ مِّمَّن مَّعَكَۚ\nفبارك الله في الجميع حتى ملأوا أقطار الأرض ونواحيها. السعدي:٣٨٣.\nبارك الله في ذرية من كان مع نوحٍ -عليه السلام- في السفينة؛ فما مظهر هذه البركة؟\nتِلۡكَ مِنۡ أَنۢبَآءِ ٱلۡغَيۡبِ نُوحِيهَآ إِلَيۡكَۖ مَا كُنتَ تَعۡلَمُهَآ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَٰقِبَةَ لِلۡمُتَّقِينَ ٤٩\nكما صبر نوح -عليه السّلام- فكانت العاقبة له، كذلك تكون العاقبة لك على قومك. ابن عاشور:١٢/٩٣.\nلمَ أمر الرسول بالصبر بعد قصة نوح -عليه السلام-؟\nوَيَٰقَوۡمِ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا وَيَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡاْ مُجۡرِمِينَ ٥٢\nوفي الآية دليل على أن الاستغفار والتوبة سبب لنزول الأمطار... والمراد بالتوبة هنا الرجوع عن الكفر، ثم عن الذنوب؛ لأن التوبة من الذنوب لا تصح إلا بعد الإيمان. ابن جزي: ١/٣٩٩.\nبيّن شيئًا من فوائد الاستغفار."],[228,"§هود\nwords\nاعتَرَاكَأَصَابَكَ.\nفَكِيدُونِيفَاجتَهِدُوا فِي إِيصَالِ الضُّرِّ إِلَيَّ.\nثُمَّ لا تُنظِرُونِلا تُمهِلُونِي.\nآخِذٌ بِنَاصِيَتِهَامَالِكُهَا، وَالمُتَصَرِّفُ فِيهَا.\nوَاستَعمَرَكُم فِيهَاجَعَلَكُم عُمَّارًا لَهَا.\nكُنتَ فِينَا مَرجُوًّاكُنَّا نَرجُو أَن تَكُونَ سَيِّدًا.\ndeeds\nأَشهِدِ الله تعالى على براءتك من جميع أنواع الشرك الموجودة.\nحدد أمرًا أهمك، وفوض أمرك فيه إلى الله تعالى، مع الأخذ بالأسباب؛ فإن تولى الله أمرك كفاك.\nذكِّر من حولك بنعم الله تعالى عليهم وإحسانه لهم.\nguid\nقوة التوكل على الله سبحانه تغرس الشجاعة في نفس المؤمن.\nالتوكل على الله سببٌ لنجاحك الدنيوي والأخروي.\nالكبر والعناد من شر الصفات الخلقية في الإِنسان.\nrefl\nفَكِيدُونِي جَمِيعٗا ثُمَّ لَا تُنظِرُونِ ٥٥ إِنِّي تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّي وَرَبِّكُمۚ مَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٥٦\nوهذا القول مع كثرة الأعداء يدل على كمال الثقة بنصر الله تعالى. القرطبي:١١/١٤٣.\nعلى أي شيء يدل قول هود -عليه السلام-؟\nمَّا مِن دَآبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ إِنَّ رَبِّي عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٥٦\nأي: نفس تدب على الأرض... ﴿إِلَّا هُوَ ءَاخِذُۢ بِنَاصِيَتِهَآۚ﴾ أي: يصرفها كيف يشاء، ويمنعها مما يشاء. القرطبي:١١/١٤٣.\nبينت الآية شيئًا من قدرة الله، وضعف المخلوقين، وضحه.\nفَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ رَبِّي قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ ٥٧\n(ولا تضرونه شيئًا): بتوليكم وإعراضكم؛ إنَّما تضرون أنفسكم، وقيل: لا تنقصونه شيئًا إذا أهلككم؛ لأن وجودكم وعدمه عنده سواء. البغوي:٢/٤٠٩.\nهل يضر العبد ربه بتوليه وإعراضه عن طاعة الله تعالى؟\nوَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا هُودٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَنَجَّيۡنَٰهُم مِّنۡ عَذَابٍ غَلِيظٖ ٥٨\nلأن أحدًا لا ينجو إلا برحمة الله تعالى، وإن كانت له أعمال صالحة. القرطبي:١١/١٤٦.\nهل يستطيع أحد أن ينجو من العذاب بعمله الصالح فقط؟\nوَتِلۡكَ عَادٞۖ جَحَدُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَعَصَوۡاْ رُسُلَهُۥ وَٱتَّبَعُوٓاْ أَمۡرَ كُلِّ جَبَّارٍ عَنِيدٖ ٥٩\nمن عصى رسولًا واحدًا لزمه عصيان جميعهم؛ فإنهم متفقون على الإيمان بالله، وعلى توحيده. ابن جزي:١/٤٠٠.\nدلت هذه الآية على أن من كذب رسولًا واحدًا فقد كذب جميع الرسل، وضح ذلك.\nفَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ ٦١\nوفي هذه الآية... قربٌ يقتضي إلطافه تعالى بهم، وإجابته لدعواتهم، وتحقيقه لمراداتهم؛ ولهذا يقرن باسمه القريب اسمه المجيب. السعدي:٣٨٥.\nلماذا قرن الله -سبحانه وتعالى- اسمه القريب بالمجيب؟\nقَالُواْ يَٰصَٰلِحُ قَدۡ كُنتَ فِينَا مَرۡجُوّٗا قَبۡلَ هَٰذَآۖ\nأي: قد كنا نرجوك، ونؤمل فيك العقل والنفع، وهذا شهادة منهم لنبيهم صالح أنه ما زال معروفًا بمكارم الأخلاق، ومحاسن الشيم، وأنه من خيار قومه. السعدي:٣٨٥.\nالعالم والداعية يجمع بين الدين والخلق الحسن، بَيِّن ذلك من خلال هذه الآية."],[229,"§هود\nwords\nتَخسِيرٍتَضلِيلٍ، وَإِبعَادٍ عَنِ الخَيرِ.\nفَعَقَرُوهَافَنَحَرُوهَا.\nجَاثِمِينَهَامِدِينَ، سَاقِطِينَ عَلَى وُجُوهِهِم.\nنَكِرَهُمأَنكَرَ ذَلِكَ مِنهُم.\ndeeds\nحدد منكرٍا، وأَنكِره بأسلوب مقنع وحكيم.\nقل: \"اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك، وبك منك؛ لا أحصي ثناءً عليك، أنت كما أثنيت على نفسك\".\nادع أحد زملائك الذين يساعدونك على الخير إلى منزلك، وأكرمه اقتداءً بكرم إبراهيم -عليه السلام-.\nguid\nعلى الداعية إلى الله أن يكون على بينةٍ فيما يدعو إليه؛ وذلك بالتثبت من المسائل قبل الكلام فيها.\nالمؤمن يعلم أن الخير الذي يعيش فيه من هدايةٍ وصلاح وتقوى إنَّما هو فضل من الله ورحمة.\nالذي يدعوك إلى المعصية لن يستطيع أن يدفع عنك عذاب الله، فتمسك بطاعة الله.\nrefl\nوَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ\nوإضافة النّاقة إلى اسم الجلالة؛ لأنّها خُلقت بقدرة الله الخارقة للعادة. ابن عاشور:١٢/١١٣.\nلماذا أضيفت الناقة إلى اسم الجلالة؟\nفَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ ٦٥\n(فعقروها): إنَّما عقرها بعضهم، وأضيف إلى الكل؛ لأنه كان برضا الباقين. القرطبي:١١/١٥٤.\nنرى من الناس من لا يفعل المنكر، لكنه يرضى به فلا يغيره، فما حكمه؟\nوَأَخَذَ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ ٦٧\nوعبّر عن ثمود بالّذين ظلموا للإيماء بالموصول إلى علّة ترتب الحكم؛ أي: لظلمهم؛ وهو ظلم الشّرك، وفيه تعريض بمشركي أهل مكّة بالتّحذير من أن يصيبهم مثل ما أصاب أولئك؛ لأنّهم ظالمون أيضًا. ابن عاشور:١٢/١١٤.\nلماذا عبر عن ثمود بـ﴿ٱلَّذِينَ ظَلَمُواْ﴾؟\nوَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ\nففي هذا أن السلام قبل الكلام. السعدي:٣٨٥.\nماذا نفيد من ابتداء الملائكة بالسلام؟\nفَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ ٦٩\nفي هذه الآية من أدب الضيف أن يعجل قراه، فيقدم الموجود الميسر في الحال، ثم يتبعه بغيره إن كان له جِدة، ولا يتكلف ما يضر به. القرطبي:١١/١٥٩.\nبيّن شيئًا من أدب الضيافة المستفاد من الآية.\nفَلَمَّا رَءَآ أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۚ قَالُواْ لَا تَخَفۡ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ ٧٠\nقال قتادة: \"وذلك أنهم كانوا إذا نزل بهم ضيف فلم يأكل من طعامهم ظنوا أنه لم يأت بخير، وإنَّما جاء بشرٍّ\". البغوي:٢/٤١٢.\nلماذا خاف إبراهيم -عليه السلام- من الملائكة حينما لم يأكلوا من طعامه؟\nإِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمِ لُوطٖ ٧٠ وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ\nإنا أرسلنا إلى قوم لوط؛ لنهلكهم، فضحكت سارة استبشارًا بهلاكهم؛ لكثرة فسادهم، وغلظ كفرهم وعنادهم. ابن كثير:٢/٤٣٣.\nلماذا فرحت سارة وضحكت بخبر الملائكة؟"],[230,"§هود\nwords\nبَعلِيزَوجِي.\nالرَّوعُالخَوفُ.\nأَوَّاهٌكَثِيرُ التَّضَرُّعِ وَالدُّعَاءِ.\nمُنِيبٌتَائِبٌ يَرجِعُ إِلَى اللهِ فِي أُمُورِهِ كُلِّهَا.\nسِيءَ بِهِمسَاءَهُ مَجِيئُهُم.\nوَضَاقَ بِهِم ذَرعًاضَاقَ صَدرُهُ، وَاغتَمَّ لِمَجِيئِهِم؛ خَوفًا عَلَيهِم مِن قَومِهِ.\nعَصِيبٌشَدِيدٌ.\nيُهرَعُونيُسرِعُونَ.\ndeeds\nاسأل الله سبحانه الرحمة والهداية للعاصين.\nابحث عن بعض الأخبارٍ السارة، وبشِّر بها من حولك، لتدخل السرور عليهم.\nسل الله تعالى أن يرزقك الحلم والإنابة إليه سبحانه.\nguid\nقضاء الله إذا جاء لا يرده أحد.\nإذا كان خليل الرحمن كثير التوبة والإنابة إلى الله سبحانه؛ فما بالنا نقصر في التوبة والإنابة؟!\nلا يأس من الذرية الصالحة.\nrefl\nقَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ\nفإن أمره لا عجب فيه؛ لنفوذ مشيئته التامة في كل شيء، فلا يستغرب على قدرته شيء. السعدي:٣٨٦.\nلماذا كان لا ينبغي لامرأة إبراهيم أن تعجب من أمر الله؟\nفَلَمَّا ذَهَبَ عَنۡ إِبۡرَٰهِيمَ ٱلرَّوۡعُ وَجَآءَتۡهُ ٱلۡبُشۡرَىٰ يُجَٰدِلُنَا فِي قَوۡمِ لُوطٍ ٧٤\nالمجادلة مع الملائكة، وعدّيت إلى ضمير الجلالة؛ لأنّ المقصود من جدال الملائكة التعرّض إلى أمر الله بصرف العذاب عن قوم لوط. ابن عاشور:١٢/١٢٣.\nالمجادلة مع الملائكة، ومع هذا عديت إلى ضمير الجلالة، لماذا؟\nإِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٞ مُّنِيبٞ ٧٥\n﴿إِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ﴾ أي: ذو خلق حسن، وسعة صدر، وعدم غضب عند جهل الجاهلين. (أواه) أي: متضرع إلى الله في جميع الأوقات. (منيب) أي: رجَّاع إلى الله بمعرفته ومحبته، والإقبال عليه، والإعراض عمن سواه؛ فلذلك كان يجادل عمن حتَّم الله بهلاكهم. السعدي:٣٨٦.\nما أبرز صفات إبراهيم -عليه السلام- حتى نقتدي به؟\nإِنَّ إِبۡرَٰهِيمَ لَحَلِيمٌ أَوَّٰهٞ مُّنِيبٞ ٧٥\nالمنيب: الراجع... وإبراهيم كان راجعًا إلى الله تعالى في أموره كلها. وقيل: الأواه: المتأوه أسفًا على ما قد فات قوم لوط من الإيمان. القرطبي:١١/١٧٣.\nرحمة الأنبياء بأقوامهم تحملهم على الضيق مما يجري عليهم من العقوبات، وضح ذلك.\nفَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ ٧٨\nوالاستفهام في ﴿أَلَيۡسَ مِنكُمۡ رَجُلٌ رَّشِيدٌ﴾ إنكار وتوبيخ؛ لأنّ إهانة الضيف مسبّة لا يفعلها إلّا أهل السفاهة. ابن عاشور:١٢/١٢٩.\nما فائدة الاستفهام في قوله تعالى: ﴿أَلَيۡسَ مِنكُمۡ رَجُلٌ رَّشِيدٌ﴾؟\nأَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ ٧٨\nأي: شديد يأمر بالمعروف وينهى عن المنكر، والرشد والرشاد: الهدى والاستقامة. القرطبي: ١١/١٧٣.\nما صفات الرجل الرشيد؟\nقَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ ٨١\nنُهوا عن الالتفات لئلَّا تتفطر أكبادهم على قريتهم. ابن جزي:١/٤٠٣.\nفي نهي الله تعالى لوطًا وأهله عن الالتفات لفتة، اذكرها."],[231,"§هود\nwords\nسِجِّيلٍطِينٍ مُتَصَلِّبٍ مَتِينٍ.\nمَنضُودٍصُفَّ بَعضُهَا إِلَى بَعضٍ مُتَتَابِعَةً.\nمُسَوَّمَةًمُعَلَّمَةً عِندَ اللهِ بِعَلامَةٍ مَعرُوفَةٍ لا تُشبِهُ حِجَارَةَ الأَرضِ.\nبَقِيَّتُ اللَّهِمَا يُبقِي اللهُ لَكُم بَعدَ إِيفَاءِ الكَيلِ وَالمِيزَانِ مِنَ الرِّبحِ الحَلالِ.\ndeeds\nفتش في نفسك: هل ظلمت أحدًا في عرض، أو مال، أو غيره، ثم رُدّ الحقوق لأهلها.\nحدد عملًا صالحًا، وتبين أحكامه الشرعية، واعمل به، ثم ادع من حولك إليه.\nكلما أقدمت على عمل هذا اليوم قل قبله: \"اللهم وفقني فيه لما تحبه وترضاه\".\nguid\nالكبائر ليست سواء؛ فبعضها أشد عقوبة من بعض.\nالربـح القليل الحـلال خيرٌ وأكثـر بـركة من الربـح الكثير الحـرام.\nمن أراد أن يدعوَ إلى خير؛ فعليه أن يكون على بينةٍ وفهم وتثبت لما يدعو إليه.\nrefl\nمُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٖ ٨٣\nالمعنى: ما الحجارة من ظالمي قومك يا محمد ببعيد، وقال قتادة وعكرمة: \"ظالمي هذه الأمة، والله ما أجار الله منها ظالمًا بعد\". القرطبي:١١/١٨٩.\nهل هذه العقوبات الإلهية خاصة بهؤلاء، أم أنها قد تنزل بالظالمين في أي زمن؟\nوَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ\nكانوا مع كفرهم أهل بخس وتطفيف؛ كانوا إذا جاءهم البائع بالطعام أخذوا بكيل زائد واستوفوا بغاية ما يقدرون عليه وظلموا، وإن جاءهم مشتر للطعام باعوه بكيل ناقص وشححوا له بغاية ما يقدرون. القرطبي:١١/١٩١\nبيّن خطر ظلم الناس في أرزاقهم ومعايشهم، وكيف كان سببًا في الهلاك.\nبَقِيَّتُ ٱللَّهِ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَۚ وَمَآ أَنَا۠ عَلَيۡكُم بِحَفِيظٖ ٨٦\nأي: ما يبقيه الله لكم بعد إيفاء الحقوق بالقسط أكثر بركة، وأحمد عاقبة مما تبقونه لأنفسكم من فضل التطفيف بالتجبر والظلم. القرطبي:١١/١٩٢.\nهل العبرة بكثرة المال، أم ببركته؟ وضح ذلك من خلال الآية.\nقَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ ٨٧\nوهذا القول الذي أخرجوه بصيغة التهكم وأن الأمر بعكسه ليس كما ظنوه؛ بل الأمر كما قالوه: إن صلاته تأمره أن ينهاهم عما كان يعبد آباؤهم الضالون، وأن يفعلوا في أموالهم ما يشاؤون؛ فإن الصلاة تنهى عن الفحشاء والمنكر، وأي فحشاء ومنكر أكبر من عبادة غير الله؟! ومن منع حقوق عباد الله أو سرقتها بالمكاييل والموازين؟! وهو -عليه الصلاة والسلام- الحليم الرشيد. السعدي:٣٨٧.\nذُكِر في الآية مقصد من مقاصد الصلاة، بيِّن ذلك.\nقَالُواْ يَٰشُعَيۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا يَعۡبُدُ ءَابَآؤُنَآ أَوۡ أَن نَّفۡعَلَ فِيٓ أَمۡوَٰلِنَا مَا نَشَٰٓؤُاْۖ إِنَّكَ لَأَنتَ ٱلۡحَلِيمُ ٱلرَّشِيدُ ٨٧\nفلما كانت الصلاة أخص أعماله المخالفة لمعتادهم جعلوها المشيرة عليه بما بلّغه إليهم من أمور مخالفة لمعتادهم. ابن عاشور:١٢/١٤١.\nارتبط الأنبياء -عليهم السلام- بالصلاة حتى أصبحت عبادة مؤثرة في سائر أعمال حياتهم، بين ذلك.\nوَمَآ أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَآ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ\nأي: ليس أنهاكم عن شيء وأرتكبه، كما لا أترك ما أمرتكم به. ﴿إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ﴾ أي: ما أريد إلا فعل الصلاح؛ أي: أن تصلحوا دنياكم بالعدل، وآخرتكم بالعبادة. القرطبي:١١/١٩٨.\nنصت الآية على الإصلاح، فبم يتم ذلك؟\nإِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ\n﴿إِنۡ أُرِيدُ إِلَّا ٱلۡإِصۡلَٰحَ مَا ٱسۡتَطَعۡتُۚ﴾: ولما كان هذا فيه نوع تزكية للنفس، دفع هذا بقوله: ﴿وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ﴾ أي: وما يحصل لي من التوفيق لفعل الخير والانفكاك عن الشر إلا بالله تعالى؛ لا بحولي ولا بقوتي. السعدي:٣٨٧.\nلماذا بعد أن أخبرهم بأنه يريد الإصلاح أتبع ذلك بقوله: ﴿وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ﴾؟"],[232,"§هود\nwords\nلا يَجرِمَنَّكُملا يَحمِلَنَّكُم.\nشِقَاقِيعَدَاوَتِي.\nرَهطُكَعَشِيرَتُكَ.\nوَرَاءَكُم ظِهرِيًّامَنبُوذًا خَلفَ ظُهُورِكُم.\nمَكَانَتِكُمطَرِيقَتِكُم وَحَالَتِكُم.\ndeeds\nذكر من حولك أن سنن الله تعالى لا تحابي أحدًا.\nاقرأ دعاء سيد الاستغفار في الصباح وفي المساء.\nادع الله تعالى باسميه (الرحيم) و(الودود)؛ لعله ينفتح لك من أبواب الخير الشيءُ الكثير.\nguid\nلا تكن مشكلتك مع بعض الدعاة أو الصالحين حيلة للشيطان عليك لتركك الصلاح والعبادة.\nاشتداد الأزمات مؤذن بقرب انفراجها.\nاتباع قوم فرعون لفرعون -على جهله وتجبره- دليل على شدة فتنة الأتباع؛ فليكن الدليل الصحيح قائدك، لا مجرد أقوال الرجال.\nrefl\nوَيَٰقَوۡمِ لَا يَجۡرِمَنَّكُمۡ شِقَاقِيٓ أَن يُصِيبَكُم مِّثۡلُ مَآ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَٰلِحٖۚ\nوفي قصة شعيب من الفوائد والعبر:... الترهيب بأخذات الأمم وما جرى عليهم. وأنه ينبغي أن تذكر القصص التي فيها إيقاع العقوبات بالمجرمين في سياق الوعظ والزجر. كما أنه ينبغي ذكر ما أكرم الله به أهل التقوى عند الترغيب والحث على التقوى. السعدي:٣٨٩.\nفي هذه الآية أسلوبٌ دعويٌّ اتبعه شعيب -عليه السلام- مع قومه، فما هو؟\nوَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ ٩٠\nوللودود معنيان؛ أحدهما: أنه محب للمؤمنين، وقيل: بمعنى المودود، أي: محبوب للمؤمنين. البغوي:٢/٤٢١.\nبيّن معنى اسم (الودود)، وماذا تفيد من هذه الآية؟\nقَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفٗاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ ٩١ قَالَ يَٰقَوۡمِ أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ\nتهاونهم به -وهو رسول الله- تهاون بالله؛ فلذلك قال: ﴿أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَآءَكُمۡ ظِهۡرِيًّاۖ﴾. ابن جزي:١/٤٠٤.\nانتقاص العالم أو الداعية بسبب دينه انتقاصٌ لله -عز وجل-، بين ذلك.\nقَالُواْ يَٰشُعَيۡبُ مَا نَفۡقَهُ كَثِيرٗا مِّمَّا تَقُولُ\nوذلك لبغضهم لما يقول، ونفرتهم عنه. السعدي:٣٨٨.\nما السبب في عدم فهم قوم شعيب لكلامه -عليه السلام-؟\nوَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَٰكَۖ وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ ٩١\nالله يدفع عن المؤمنين بأسباب كثيرة؛ قد يعلمون بعضها وقد لا يعلمون شيئًا منها، وربما دفع عنهم بسبب قبيلتهم، أو أهل وطنهم الكفار؛ كما دفع الله عن شعيب رجم قومه بسبب رهطه، وأن هذه الروابط التي يحصل بها الدفع عن الإسلام والمسلمين لا بأس بالسعي فيها، بل ربما تعين ذلك؛ لأن الإصلاح مطلوب على حسب القدرة والإمكان. السعدي:٣٨٩.\nهل يجوز للمسلم أن يسعى لتحقيق أسباب دنيوية يكون فيها حماية لدينه؟\nوَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡبٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَأَخَذَتِ ٱلَّذِينَ ظَلَمُواْ ٱلصَّيۡحَةُ فَأَصۡبَحُواْ فِي دِيَٰرِهِمۡ جَٰثِمِينَ ٩٤\nذكر هاهنا أنه: أتتهم صيحة، وفي الأعراف: رجفة، وفي الشعراء: عذاب يوم الظلة؛ وهم أمة واحدة اجتمع عليهم -يوم عذابهم- هذه النقم كلها، وإنَّما ذكر في كل سياق ما يناسبه. ابن كثير:٢/٤٣٩.\nذكر الله عن قوم شعيب ثلاثة أوصاف لعذابهم، فكيف تجمع بين هذه الآيات؟\nوَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ٩٦ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ\nأي: أشراف قومه؛ لأنهم المتبوعون، وغيرهم تبع لهم. السعدي:٣٨٩.\nلماذا خُصَّ ملأ فرعون وأشراف قومه بالذكر، مع أن موسى مرسلٌ لجميع القوم؟"],[233,"§هود\nwords\nفَأَورَدَهُمفَأَدخَلَهُم.\nالمَورُودالمَدخُولُ فِيهِ، وَهُوَ هُنَا النَّارُ.\nالرِّفدُالعَونُ، وَالعَطَاءُ.\nالمَرفُودُالمُعطَى لَهُم.\nوَحَصِيدٌمَحصُودٌ قَد مُحِيَت آثَارُهُ، وَلَم يَبقَ مِنهُ شَيءٌ.\ndeeds\nاقرأ قصة من قصص القرآن، متأملًا ومستخرجًا دروسها وعبرها.\nاقرأ سورة يوسف متأملًا ظلم الأفراد، واقرأ سورة هود متأملًا ظلم أهل القرى، واستعذ بالله منهما.\nاقرأ آيات من القرآن من آيات الوعيد؛ سائلًا الله أن يرزقك الخوف منه.\nguid\nالجزاء من جنس العمل؛ فكما يكون الطاغية متقدمًا على قومه بالباطل في الدنيا فهو سابق لهم في العذاب يوم القيامة.\nتنزه الله تعالى عن الظلم في إهلاك أهل الشرك والمعاصي.\nالقصص القرآني ليس للتسلية، وإنَّما للتذكر والاتعاظ.\nrefl\nيَقۡدُمُ قَوۡمَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ ٩٨\nيعني: يتقدمهم إلى النار؛ إذ هو رئيسهم. القرطبي:١١/٢٠٤.\nمن تقدم الناس إلى الشر في الدنيا تقدمهم إلى النار يوم القيامة، وضح ذلك.\nيَقۡدُمُ قَوۡمَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ ٩٨\nوكما أنهم اتبعوه في الدنيا، وكان مقدمهم ورئيسهم، كذلك هو يقدمهم يوم القيامة إلى نار جهنم فأوردهم إياها، وشربوا من حياض رداها، وله في ذلك الحظ الأوفر، ومن ثم العذاب الأكبر. ابن كثير:٢/٤٤٠.\nلمَ كان فرعون يوم القيامة هو مقدم قومه؟\nوَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن ظَلَمُوٓاْ أَنفُسَهُمۡۖ\n﴿وَظَلَمُوٓاْ أَنفُسَهُمۡ﴾: بالكفر والمعصية. البغوي:٢/٤٢٣.\nكيف يظلم العبد نفسه؟\nفَمَآ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِي يَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَيۡءٖ لَّمَّا جَآءَ أَمۡرُ رَبِّكَۖ\nوهكذا كل من التجأ إلى غير الله؛ لم ينفعه ذلك عند نزول الشدائد. السعدي:٣٨٩.\nما حال من لجأ إلى غير الله تعالى؟\nوَكَذَٰلِكَ أَخۡذُ رَبِّكَ إِذَآ أَخَذَ ٱلۡقُرَىٰ وَهِيَ ظَٰلِمَةٌۚ إِنَّ أَخۡذَهُۥٓ أَلِيمٞ شَدِيدٌ ١٠٢\nالكاذب الفاجر وإن أعطي دولة فلا بد من زوالها بالكلية، وبقاء ذمِّه ولسان السوء له في العالم، وهو يظهر سريعًا ويزول سريعًا. ابن تيمية:٣/٥٥٧.\nما صفة أخذ الله سبحانه للقرى الظالمة من خلال الآية؟\nفَأَمَّا ٱلَّذِينَ شَقُواْ فَفِي ٱلنَّارِ لَهُمۡ فِيهَا زَفِيرٞ وَشَهِيقٌ ١٠٦\nوخص بالذّكر من أحوالهم في جهنّم الزّفير والشّهيق تنفيرًا من أسباب المصير إلى النّار؛ لما في ذكر هاتين الحالتين من التّشويه بهم، وذلك أخوف لهم من الألم. ابن عاشور:١٢/١٦٥.\nلماذا خصت حالتا الزفير والشهيق؟\nفَأَمَّا ٱلَّذِينَ شَقُواْ فَفِي ٱلنَّارِ لَهُمۡ فِيهَا زَفِيرٞ وَشَهِيقٌ ١٠٦\nالزفير في الحلق، والشهيق في الصدر، أي: تنفسهم زفير، وأخذهم النفس شهيق؛ لما هم فيه من العذاب، عياذًا بالله من ذلك. ابن كثير:٢/٤٤١.\nما المراد من وصف حال أهل جهنم بأن لهم فيها زفيرًا وشهيقًا؟"],[234,"§هود\nwords\nتَكُلاَ تَكُن.\nمِريَةٍشَكٍّ.\nوَلا تَطغَوالا تَتَجَاوَزُوا مَا حَدَّهُ اللهُ لَكُم.\nوَلا تَركَنُوالا تَمِيلُوا.\nأُولُو بَقِيَّةٍبَقَايَا مِن أَهلِ الخَيرِ وَالصَّلاَحِ.\nأُترِفُوا فِيهِمُتِّعُوا فِيهِ مِن لَذَّاتِ الدُّنيَا.\ndeeds\nابحث عن جليس صالح؛ تصاحبه هذا اليوم، ولا تركن للفسقة والظلمة فتحشر معهم.\nحافظ على أداء الصلوات أول وقتها مع الجماعة؛ خاصة صلاتي الفجر والعصر.\nأنكر على بعض أهل البدع أو المجاهرين بالمعاصي بأسلوب حكيم.\nguid\nلا يُعتبر الشخص مستقيمًا على الإسلام؛ حتى يكون موافقًا لما جـاء في القرآن والسنة، مبتعدًا عن هوى نفسه.\nابتعد عن الظلم والظلمة بقدر الإمكان.\nمن أسباب الانحراف الإكثار من التنعم والترفه.\nrefl\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ\nوإذا كانت هذه حالهم مع كتابهم؛ فمع القرآن الذي أوحاه الله إليك غير مستغرب من طائفة اليهود أن لا يؤمنوا به، وأن يكونوا في شك منه مريب. السعدي:٣٩٠.\nالمشككون بالقرآن فيهم شبه باليهود، وضح ذلك من خلال الآية.\nفَٱسۡتَقِمۡ كَمَآ أُمِرۡتَ وَمَن تَابَ مَعَكَ\nيأمر تعالى رسوله وعباده المؤمنين بالثبات والدوام على الاستقامة؛ وذلك من أكبر العون على النصر على الأعداء، ومخالفة الأضداد. ابن كثير:٢/٤٤٣.\nما وجه ذكر الأمر بالاستقامة بعد ذكر المخالفين للنبي والمعادين له؟\nوَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَ ثُمَّ لَا تُنصَرُونَ ١١٣\nقال ابن عباس -رضي الله عنهما-: \"ولا تميلوا\"، والركون هو: المحبة، والميل بالقلب، وقال أبو العالية: \"لا ترضوا بأعمالهم\"، وقال السدي: \"لا تداهنوا الظلمة\". البغوي:٢/٤٢٨.\nما علامة الركون إلى الظلمة؟\nوَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ٱلنَّارُ\nدالة على هجران أهل الكفر والمعاصي من أهل البدع وغيرهم؛ فإن صحبتهم كفر أو معصية؛ إذ الصحبة لا تكون إلا عن مودة. القرطبي:١١/٢٢٦.\nما الواجب على المؤمن في اختيار الصحبة والرفقة؟\nوَلَا تَرۡكَنُوٓاْ إِلَى ٱلَّذِينَ ظَلَمُواْ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِيَآءَ ثُمَّ لَا تُنصَرُونَ ١١٣\nوإذا كان هذا الوعيد في الركون إلى الظلمة؛ فكيف حال الظلمة بأنفسهم؟! نسأل الله العافية من الظلم. السعدي:٣٩١.\nهذه الآية فيها وعيد شديد للظمة، كيف نستنبط ذلك؟\nوَأَقِمِ ٱلصَّلَوٰةَ طَرَفَيِ ٱلنَّهَارِ وَزُلَفٗا مِّنَ ٱلَّيۡلِۚ إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِۚ ذَٰلِكَ ذِكۡرَىٰ لِلذَّٰكِرِينَ ١١٤\nوخصها بالذكر لأنها ثانية الإيمان، وإليها يفزع في النوائب، وكان النبي إذا حزبه أمر فزع إلى الصلاة. القرطبي:١١/٢٢٧.\nبيّن عظمة الصلاة من خلال هذه الآية.\nوَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ١١٥\nومناسبة وقوع الأمر بالصّبر عقب الأمر بالاستقامة والنّهي عن الركون إلى الذين ظلموا: أنّ المأمورات لا تخلو عن مشقة عظيمة، ومخالفة لهوى كثير من النفوس؛ فناسب أن يكون الأمر بالصبر بعد ذلك؛ ليكون الصبر على الجميع؛ كلٌ بما يناسبه. ابن عاشور:١٢/١٨٢.\nما مناسبة وقوع الأمر بالصبر بعد الأمر بالاستقامة؟"],[235,"§هود ، يوسف\nwords\nأُمَّةً وَاحِدَةًجَمَاعَةً وَاحِدَةً عَلَى دِينٍ وَاحِدٍ، وَهُوَ الإِسلامُ.\nمَكَانَتِكُمحَالَتِكُم، وَطَرِيقَتِكُم.\nلَمِنَ الغَافِلِينَأَي: لا تَدرِي عَن قَصَصِ السَّابِقِينَ شَيئًا.\ndeeds\nأصلح اليوم بين مختلفين؛ فإن الخلاف سنة كونية، والألفة سنة شرعية.\nتذكر أمرًا أهمك، ثم قل: \"حسبي الله لا إله إلا هو عليه توكلت وهو رب العرش العظيم\".\nقسِّم قصَّة يوسف -عليه السلام- إلى مقاطع، ثم تدرَّب على إلقائها على الطلاب للموعظة والتذكير.\nguid\nابتعد عن مواطن الخلاف والفرقة، وليكن هدفك الاجتماع مع المؤمنين والصالحين على السنة والجماعة.\nلا تنتفع بالقرآن الكريم إلا بعد الإنصات والرغبة في الاستفادة.\nقصُّ القصص الهادفة من الوسائل التربوية والتعليمية الناجحة.\nrefl\nوَلَوۡ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةٗ وَٰحِدَةٗۖ وَلَا يَزَالُونَ مُخۡتَلِفِينَ ١١٨ إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَٰلِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ ١١٩\nفأخبر أن أهل الرحمة لا يختلفون، وأهل الرحمة هم أتباع الأنبياء قولًا وفعلًا، وهم أهل القرآن والحديث من هذه الأمة؛ فمن خالفهم في شيء فاته من الرحمة بقدر ذلك. ولهذا لمَّا كانت الفلاسفة أبعد عن اتباع الأنبياء كانوا أعظم اختلافًا، والخوارج والمعتزلة والروافض لمَّا كانوا أيضًا أبعد عن السنة والحديث كانوا أعظم افتراقًا في هذه؛ لا سيما الرافضة؛ فإنه يقال: إنهم أعظم الطوائف اختلافًا؛ وذلك لأنهم أبعد الطوائف عن السنة والجماعة. ابن تيمية:٣/٥٦٢.\nكيف بينت الآية أن أهل السنة أقل الناس اختلافًا، وأن أهل البدع أكثر الناس اختلافًا؟\nوَكُلّٗا نَّقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ\nليطمئن ويثبت ويصبر كما صبر أولو العزم من الرسل؛ فإن النفوس تأنس بالاقتداء، وتنشط على الأعمال، وتريد المنافسة لغيرها، ويتأيد الحق بذكر شواهده وكثرة من قام به. السعدي:٣٩٢.\nما الأوجه الموجودة في القصص والتي تثبت الفؤاد وتطمئنه؟\nوَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَإِلَيۡهِ يُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَيۡهِۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ ١٢٣\nالتوكل والاستعانة هي من عبادة الله، لكن خُصَّت بالذكر ليقصدها المتعبد بخصوصها؛ فإنها هي العون على سائر أنواع العبادة؛ إذ هو سبحانه لا يُعبد إلا بمعونته. ابن تيمية:٣/٥٦٣.\nلماذا خص التوكل بالذكر مع أنه داخل في جملة العبادة؟\nإِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ ٢\nوذلك لأن لغة العرب أفصح اللغات، وأبينها، وأوسعها، وأكثرها تأدية للمعاني التي تقوم بالنفوس؛ فلهذا أنزل أشرف الكتب بأشرف اللغات. ابن كثير:٢/٤٤٨.\nلماذا نزل القرآن باللغة العربية؟\nإِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ ٢\nأنزل أشرف الكتب بأشرف اللغات، على أشرف الرسل، بسفارة أشرف الملائكة، وكان ذلك في أشرف بقاع الأرض، وابتُدِئ إنزاله في أشرف شهور السنة؛ وهو رمضان؛ فكَمُلَ من كل الوجوه. ابن كثير:٢/٤٤٨.\nشَرُفَ القرآن من وجوه متعددة، بَيِّن هذه الوجوه.\nنَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ ٱلۡقَصَصِ\nهذه القصة من أحسن القصص، وأوضحها، وأبينها؛ لما فيها من أنواع التنقلات من حالٍ إلى حال، ومن محنة إلى محنة، ومن محنة إلى منحة ومِنَّة، ومن ذل إلى عز، ومن رق إلى ملك، ومن فرقة وشتات إلى اجتماع وائتلاف، ومن حزن إلى سرور، ومن رخاء إلى جدب، ومن جدب إلى رخاء، ومن ضيق إلى سعة، ومن إنكار إلى إقرار. السعدي:٤٠٧.\nلماذا كانت قصة يوسف من أحسن القصص؟\nنَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ ٱلۡقَصَصِ\nاعلم أن الله ذكر أنه يقص على رسوله أحسن القصص في هذا الكتاب، ثم ذكر هذه القصة -قصة يوسف- وبسطها، وذكر ما جرى فيها، فعلم بذلك أنها قصة تامة كاملة حسنة، فمن أراد أن يكملها أو يحسنها بما يذكر في الإسرائيليات التي لا يعرف لها سند ولا ناقل، وأغلبها كذب؛ فهو مُستَدرِكٌ على الله، ومُكَمِّلٌ لشيء يزعم أنه ناقص. السعدي:٣٩٣.\nما رأيك فيمن يزيدُ في قصة يوسف زياداتٍ ليست في القرآن، ولا في السنة؟"],[236,"§يوسف\nwords\nيَجتَبِيكَيَصطَفِيكَ.\nعُصبَةٌجَمَاعَةٌ ذَوُو عَدَدٍ.\nضَلالٍخَطَإٍ.\nغَيَابَةِ الجُبِّجَوفِ البِئرِ، والجُبُّ: هُوَ البِئرُ الَّذِي قُطِعَ مِنَ الأَرضِ دُونَ بِنَاءٍ يَحمِيهِ مِنَ الاِنهِيَارِ.\nيَرتَعيَأكُل مَا لَذَّ وَطَابَ.\nعُصبَةٌجَمَاعَةٌ قَوِيَّةٌ.\ndeeds\nاقرأ أحاديث في تعبير النبي لرؤيا بعض أصحابه -رضي الله عنهم-.\nاستعذ بالله من العين و الحسد؛ فهما سبب لكثير من البلاء.\nأنكر منكرًا اتفق عليه أقاربك أو أصدقاؤك.\nguid\nمن الحكمة كتمان الأمور عن من هو مظنة الغيرة أو الحسد.\nالغيرة فطرة، ولكن إذا استسلم لها الإنسان استخدمها الشيطان ليوصل صاحبها إلى الحسد، ثم الجريمة.\nلا يُلام المرء على محبة ولده.\nrefl\nقَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ ٥\n(لا تقصص رؤياك على إخوتك): إنَّما قال ذلك لأنه علم أن تأويلها ارتفاع منزلته؛ فخاف عليه من الحسد. ابن جزي:١/٤١٠.\nبينت هذه الآية سبيلًا من سبل الاحتراز من الحسد، فما هو؟\nقَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ ٥\nومن هذا يؤخذ الأمر بكتمان النعمة حتى توجد وتظهر. ابن كثير:٢/٤٥٠.\nإذا أنعم الله عليك بنعمة، فمتى تظهرها؟ ومتى تخفيها؟\nقَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ ٥\nوفي الصحيح... أن رسول الله قال: «إذا رأى أحدكم الرؤيا يُحِبُّها؛ فإنها من الله تعالى؛ فليحمد الله تعالى، وليُحَدِّث بها. وإذا رأى غير ذلك مما يكره؛ فإنما هي من الشيطان؛ فليستعذ بالله تعالى من الشيطان الرجيم ومن شرها، ولا يذكرها لأحد؛ فإنها لا تضره». وصح عن جابر أن رسول الله قال: «إذا رأى أحدكم الرؤيا يكرهها؛ فليبصق عن يساره ثلاثًا، وليستعذ بالله تعالى من الشيطان الرجيم، وليتحول عن جنبه الذي كان عليه». الألوسي:١٢/٥١٤.\nما هدي النبي في الرؤيا؟\nلَّقَدۡ كَانَ فِي يُوسُفَ وَإِخۡوَتِهِۦٓ ءَايَٰتٞ لِّلسَّآئِلِينَ ٧\nأي: لكل من سأل عنها بلسان الحال، أو بلسان المقال؛ فإن السائلين هم الذين ينتفعون بالآيات والعبر، وأمَّا المعرضون فلا ينتفعون بالآيات، ولا في القصص والبينات. السعدي:٣٩٤.\nلماذا خُصَّ السائلون بالانتفاع بالآيات؟\nٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ ٩\nوهذه آية من عبر الأخلاق السيّئة؛ وهي التّخلّص من مزاحمة الفاضل بفضله لمن هو دونه فيه أو مساويه بإعدام صاحب الفضل، وهي أكبر جريمة؛ لاشتمالها على الحسد، والإضرار بالغير، وانتهاك ما أمر الله بحفظه، وهم قد كانوا أهل دين، ومن بيت نبوة وقد أصلح الله حالهم من بعد، وأثنى عليهم، وسمّاهم الأسباط. ابن عاشور:١٢/٢٢٣.\nاشتمل موقف إخوة يوسف على عبرة عظيمة فيما تجر إليه الأخلاق السيئة؛ كالحسد، بين ذلك.\nٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ ٩\nفقدموا العزم على التوبة قبل صدور الذنب منهم؛ تسهيلًا لفعله، وإزالة لشناعته، وتنشيطًا من بعضهم لبعض. السعدي:٣٩٤.\nذكرت الآية حيلة من حيل الشيطان على الصالحين، فما هي؟\nٱقۡتُلُواْ يُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضٗا يَخۡلُ لَكُمۡ وَجۡهُ أَبِيكُمۡ وَتَكُونُواْ مِنۢ بَعۡدِهِۦ قَوۡمٗا صَٰلِحِينَ ٩\nالذنب الواحد يستتبع ذنوبًا متعددة، ولا يتم لفاعله إلا بعدة جرائم؛ فإخوة يوسف لمَّا أرادوا التفريق بينه وبين أبيه احتالوا لذلك بأنواعٍ من الحيل، وكذبوا عدة مرات، وزوروا على أبيهم في القميص والدم الذي فيه، وفي إتيانهم عشاء يبكون. السعدي:٤٠٨.\nالذنب الواحد قد يستتبع ذنوبًا متعددة، تحدث عن ذلك من خلال الآيات."],[237,"§يوسف\nwords\nوَأَجمَعُواعَزَمُوا وَصَمَّمُوا.\nسَوَّلَتزيَّنَت.\nسَيَّارَةٌجَمَاعَةٌ مِنَ المُسَافِرِينَ.\nفَأَدلَى دَلوَهُفَأَرسَلَ دَلوَهُ فِي البِئرِ؛ لِيَملَأَهَا بِالمَاءِ.\nوَأَسَرُّوهُ بِضَاعَةًكَتَمَ إِخوَةُ يُوسُفَ كَونَهُ أَخَاهُم لِيَبِيعُوهُ.\nبَخسٍقَلِيلٍ.\nمَثوَاهُمَقَامَهُ.\ndeeds\nاستعذ بالله من الكذب.\nحدد أمرًا أهمك، واصبر عليه صبرًا جميلًا، ولا تتبعه بشكوى ولا عتاب ولا أذية؛ لعل الله ييسره لك.\nأكثر اليوم من دعاء: \"رب زدني علمًا\".\nguid\nاحذر الكذب في أحوالك كلها.\nقوة الإيمان بالقدر تكسب الصبر عند المصائب.\nالإحسان في العبادة من أسباب حفظ الله ونصره وتمكينه.\nrefl\nوَجَآءُوٓ أَبَاهُمۡ عِشَآءٗ يَبۡكُونَ ١٦\nوفطنة الحاكم لا تنخدع لمثل هذه الحيل، ولا تنوط بها حكمًا، وإنَّما يناط الحكم بالبينة. ابن عاشور:١٢/٢٣٦.\nينبغي للحاكم ألا ينخدع بالدموع وحدها، بل يطالِب بالبينة؛ دلل لذلك.\nقَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ\nأي: زينت لكم أنفسكم أمرًا قبيحًا من التفريق بيني وبينه؛ لأنه رأى من القرائن والأحوال، ومن رؤيا يوسف التي قصها عليه ما دَلَّه على ما قال. السعدي:٣٩٥.\nما القرينة التي دلت على كذب إخوة يوسف؟\nفَصَبۡرٞ جَمِيلٞۖ\nقال الثوري عن بعض أصحابه أنه قال: \"ثلاث من الصبر: أن لا تحدث بوجعك، ولا بمصيبتك، ولا تزكي نفسك\". ابن كثير:٢/٤٥٣.\nبيّن بعض أنواع الصبر الجميل.\nفَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ ١٨\nو\"الصبر الجميل\" صبر بلا شكوى؛ قال يعقوب عليه الصلاة والسلام: ﴿إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ﴾ [يوسف: ٨٦] مع قوله: ﴿فَصَبۡرٌ جَمِيلٌۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ﴾؛ فالشكوى إلى الله لا تنافي الصبر الجميل. ابن تيمية:٤/٢٢.\nما الصبر الجميل؟ وهل تنافيه الشكوى لله تعالى؟\nوَجَآءَتۡ سَيَّارَةٞ فَأَرۡسَلُواْ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ يَٰبُشۡرَىٰ هَٰذَا غُلَٰمٞۚ وَأَسَرُّوهُ بِضَٰعَةٗۚ وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ ١٩\n﴿وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ﴾ أي: عليم بما يفعله إخوة يوسف ومشتروه، وهو قادر على تغيير ذلك ودفعه، ولكن له حكمة وقدر سابق؛ فترك ذلك ليمضي ما قدّره وقضاه... وفي هذا تعريض لرسوله محمد -صلى الله عليه وسلم- وإعلام له بأني عالم بأذى قومك لك، وأنا قادر على الإنكار عليهم؛ ولكني سأملي لهم، ثم أجعل لك العاقبة والحكم عليهم؛ كما جعلت ليوسف الحكم والعاقبة على إخوته. ابن كثير:٢/٤٥٤.\nما وجه ختم الآية بقوله: ﴿وَٱللَّهُ عَلِيمُۢ بِمَا يَعۡمَلُونَ﴾؟\nوَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ٢٢\nوأما النور والعلم والحكمة؛ فقد دل عليه قوله تعالى في قصة يوسف: ﴿وَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمًا وَعِلۡمًاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ﴾؛ فهي لكل محسن. ابن تيمية:٤/٢٢.\nكل محسن له نصيب من النور والعلم والحكمة، بين ذلك من الآية.\nوَلَمَّا بَلَغَ أَشُدَّهُۥٓ ءَاتَيۡنَٰهُ حُكۡمٗا وَعِلۡمٗاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ٢٢\nوفي ذكر المحسنين إيماء إلى أنّ إحسانه هو سبب جزائه بتلك النعمة. ابن عاشور:١٢/٢٤٨.\nاذكر فائدة من فوائد صفة الإحسان."],[238,"§يوسف\nwords\nوَرَاوَدَتهُدَعَتهُ إِلَى نَفسِهَا بِرِفقٍ وَلِينٍ.\nهَيتَ لَكَهَلُمَّ إِلَيَّ.\nمَثوَايَمَنزِلِي وَمُقَامِي.\nهَمَّت بِهِمَالَت نَفسُهَا لِفِعلِ الفَاحِشَةِ.\nوَهَمَّ بِهَاخَطَرَ بِقَلبِهِ إِجَابَتُهَا.\ndeeds\nاستعذ بالله تعالى وتضرع إليه من فتن السراء والضراء.\nارسل رسالة تذكر فيها باستحباب الستر على المسيء غير المجاهر، وكراهية إشاعة أخبار الفواحش بين الناس.\nحدد مجلسًا يذكرك بالمعصية، واتركه؛ محتسبًا الأجر على الله تعالى.\nguid\nاستحضار صفات الله -سبحانه وتعالى- حائل بين العبد و الوقوع في المعصية.\nتعرف على الله في الرخاء بطاعته والإقبال عليه؛ حتى يعرفك ويحفظك في الشدة.\nعاقبة الزنا والفواحش هي الخيبة والخسارة والفضيحة.\nrefl\nوَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ\nهذه المحنة العظيمة أعظم على يوسف من محنة إخوته، وصبره عليها أعظم أجرًا؛ لأنه صبر اختيار مع وجود الدواعي الكثيرة لوقوع الفعل، فقدم محبة الله عليها. وأمَّا محنته بإخوته؛ فصبره صبر اضطرار، بمنزلة الأمراض والمكاره التي تصيب العبد بغير اختياره، وليس له ملجأ إلا الصبر عليها، طائعًا أو كارهًا. السعدي:٣٩٦.\nأي المصيبتين أعظم وأكثر أجرًا بالنسبة ليوسف -عليه السلام-: مصيبته مع إخوته أو مع زوجة سيده؟ ولماذا؟\nقَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ ٢٣\n﴿مَعَاذَ ٱللَّهِۖ﴾ أي: أعوذ بالله، وأعتصم بالله مما دعوتني إليه. البغوي:٢/٤٤٩.\nبيّن عظيم شأن الاستعاذة بالله تعالى في النجاة من المعصية.\nقَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ ٢٣ وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ ٢٤\nوالحاصل أنه جعل الموانع له من هذا الفعل: تقوى الله، ومراعاة حق سيده الذي أكرمه، وصيانة نفسه عن الظلم الذي لا يفلح من تعاطاه، وكذلك ما منَّ الله عليه من برهان الإيمان الذي في قلبه؛ يقتضي منه امتثال الأوامر، واجتناب الزواجر. والجامع لذلك كله: أن الله صرف عنه السوء والفحشاء. السعدي:٣٩٦.\nما الأمور التي ساعدت يوسف -عليه السلام- في الابتعاد عن المعصية؟\nوَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ ٢٤\nقال تعالى: (ولقد همت به وهم بها لولا أن رأى برهان ربه)؛ وهو برهان الإيمان الذي حصل في قلبه؛ فصرف الله به ما كان هم به، وكتب له حسنة كاملة. ابن تيمية:٤/٣٤.\nما البرهان الذي رآه يوسف -عليه السلام-؟\nكَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ ٢٤\nفتبيّن أن الإخلاص يمنع من تسلط الشيطان؛ كما قال تعالى: ﴿كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ﴾. ابن تيمية:٤/٣٦.\nالإخلاص يمنع تسلط الشيطان، كيف عرفت ذلك من الآية؟\nوَٱسۡتَبَقَا ٱلۡبَابَ\nينبغي للعبد إذا رأى محلًا فيه فتنة وأسباب معصية أن يفر منه، ويهرب غاية ما يمكنه؛ ليتمكن من التخلص من المعصية؛ لأن يوسف -عليه السلام- لمَّا راودته التي هو في بيتها فر هاربًا يطلب الباب ليتخلص من شرها. السعدي:٤٠٩.\nماذا تفيد من هروب يوسف -عليه السلام- من مكان المعصية؟\nقَدۡ شَغَفَهَا حُبًّاۖ\nالحذر من المحبة التي يُخشى ضررها؛ فإن امرأة العزيز جرى منها ما جرى بسبب توحّدها بيوسف وحبها الشديد له؛ الذي ما تركها حتى راودته تلك المراودة، ثم كذبت عليه؛ فسجن بسببها مدة طويلة. السعدي:٤٠٩.\nما خطورة الاستسلام للحب الذي يقع خارج العلاقة الزوجية؟"],[239,"§يوسف\nwords\nوَأَعتَدَتهَيَّأَت.\nمُتَّكَأًمَا يَتَّكِئنَ عَلَيهِ مِنَ الوَسَائِدِ.\nوَقَطَّعنَجَرَحنَ.\nحَاشَ لِلهِتَنزِيهًا لِلهِ.\nالصَّاغِرِينَالأَذِلّاءِ.\nأَصبُ إِلَيهِنَّأَمِل إِلَيهِنَّ.\nأَعصِرُ خَمرًاأَعصِرُ عِنَبًا؛ لِيَصِيرَ خَمرًا.\ndeeds\nاستعذ بالله من كيد أهل السوء.\nتوجه إلى الله تعالى بالدعاء فيما أهمَّك وشغلك؛ فإنه سميع مجيب.\nأحسن إلى الناس هذا اليوم قدر استطاعتك؛ فإن ذلك مدعاة لقبول ما عندك من الحق والخير.\nguid\nمن مظاهر الصديقين إيثار السجن على معصية الله تعالى.\nالجهل ليس بقلة المعلومات، وإنَّما بكثرة الوقوع في المعاصي.\nالعذاب والضيق الدنيوي خير من لذة عاجلة يتبعها عذاب أخروي.\nrefl\nوَلَقَدۡ رَٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَئِن لَّمۡ يَفۡعَلۡ مَآ ءَامُرُهُۥ لَيُسۡجَنَنَّ وَلَيَكُونٗا مِّنَ ٱلصَّٰغِرِينَ ٣٢ قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ ٣٣\n(فاستعصم) أي: طلب العصمة، وامتنع مما أرادت منه. ﴿أَصۡبُ إِلَيۡهِنَّ﴾ أي: [أمِلْ]؛ وكلامه هذا تضرع إلى الله. ابن جزي:١/٤١٥.\nما الذي ينبغي عمله لمن تعرض لفتنة أو ابتلاء؟\nقَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ\nيوسف -عليه السلام- اختار السجن على المعصية؛ فهكذا ينبغي للعبد إذا ابتُلي بين أمرين: إما فعل معصية وإما عقوبة دنيوية، أن يختار العقوبة الدنيوية على مواقعة الذنب الموجب للعقوبة الشديدة في الدنيا والآخرة؛ ولهذا من علامات الإيمان أن يكره العبد أن يعود في الكفر بعد إذ أنقذه الله منه كما يكره أن يلقى في النار. السعدي:٤٠٩.\nإذا خُيِّرَ الشخص بين فعل معصية وعقوبة دنيوية، فماذا يختار؟\nقَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ ٣٣\nفي قول يوسف:... عبرتان؛ إحداهما: اختيار السجن والبلاء على الذنوب والمعاصي. و الثانية: طلب سؤال الله ودعائه أن يثبت القلب على دينه ويصرفه إلى طاعته، وإلا فإذا لم يثبت القلب صبا إلى الآمرين بالذنوب وصار من الجاهلين؛ ففي هذا توكل على الله واستعانة به أن يثبت القلب على الإيمان والطاعة، وفيه صبر على المحنة والبلاء والأذى الحاصل إذا ثبت على الإيمان والطاعة. ابن تيمية:٤/٣٩.\nفي الآية الكريمة عبر عظيمة، استخرج بعضها.\nثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُاْ ٱلۡأٓيَٰتِ لَيَسۡجُنُنَّهُۥ حَتَّىٰ حِينٖ ٣٥\nوعلى الجملة فكل أحوال يوسف -عليه الصلاة والسلام- لطف في عنف، ونعمة في طي بلية ونقمة، ويسر في عسر، ورجاء في يأس، وخلاص بعد لات مناص، وسائق القدر ربما يسوق القدر إلى المقدور بعنف وربما يسوقه بلطف؛ والقهر والعنف أحمد عاقبة وأقل تبعة. البقاعي:٤/٣٧.\nكيف ينبغي أن ينظر المؤمن إلى أقدار الله تعالى المؤلمة؟\nإِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِينَ ٣٦\nكان إذا مرض إنسان في السجن عاده وقام عليه، وإذا ضاق عليه المجلس وسَّع له، وإذا احتاج جمع له شيئًا، وكان يجتهد في العبادة، ويقوم الليل كله للصلاة. البغوي:٢/٤٦١.\nإلى أي حد بلغ إحسان يوسف -عليه السلام- حتى أتوا إليه، وسألوه؟\nقَالَ لَا يَأۡتِيكُمَا طَعَامٞ تُرۡزَقَانِهِۦٓ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِيلِهِۦ قَبۡلَ أَن يَأۡتِيَكُمَاۚ ذَٰلِكُمَا مِمَّا عَلَّمَنِي رَبِّيٓۚ إِنِّي تَرَكۡتُ مِلَّةَ قَوۡمٖ لَّا يُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ٣٧\nمن فطنة يوسف -عليه السلام- أنه لمَّا رأى فيهما قابلية لدعوته -حيث ظنّا فيه الظن الحسن، وقالا له: (إنا نراك من المحسنين)، وأتياه لأن يعبر لهما رؤياهما، فرآهما متشوفين لتعبيرها عنده- رأى ذلك فرصة؛ فانتهزها، فدعاهما إلى الله تعالى قبل أن يعبّر رؤياهما. السعدي:٤١٠.\nعلى الداعية أن يكون فطنًا متيقظًا للأوقات المناسبة للدعوة، وضح ذلك من الآية.\nإِنِّي تَرَكۡتُ مِلَّةَ قَوۡمٖ لَّا يُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ٣٧\nكما على العبد عبودية لله في الرخاء فعليه عبودية في الشدة؛ فيوسف -عليه السلام- لم يزل يدعو إلى الله، فلما دخل السجن استمر على ذلك، ودعا الفتيين إلى التوحيد، ونهاهما عن الشرك. السعدي:٤١٠.\nهل تقتصر العبادة على وقت الرخاء دون وقت الشدة؟"],[240,"§يوسف\nwords\nأَأَربَابٌ مُتَفَرِّقُونَأَعِبَادَةُ آلِهَةٍ شَتّى؟\nسُلطَانٍحُجّةٍ، وَبُرهَانٍ.\nرَبِّكَسَيِّدِكِ المَلِكِ.\nعِجَافٌضَعِيفَاتٌ، مَهَازِيلُ.\nتَعبُرُونَتُفَسِّرُونَ.\ndeeds\nقل في دعائك: \"اللهم إني أعوذ بك أن أشرك بك وأنا أعلم، وأستغفرك لما لا أعلم\".\nاشكر الله على نعمة الهداية؛ فإن الغافلين عن شكر هذه النعمة كثيرون.\nقم بتربية من يتعلم منك قبل أن تعلمه؛ فإن كثيرًا من الناس بأمس الحاجة للتربية والتوجيه قبل التعليم.\nguid\nاستغلال المناسبات للدعوة إلى الله تعالى؛ كما استغلها يوسف -عليه السلام-.\nالداعية يترفق بمن يدعوهم، ولا يشعرهم بالتعالي أو الإزدراء.\nاستعذ بالله من كيد الشيطان ومكره؛ فهو حريص أن ينسيك حاجاتك الدينية والدنيوية.\nrefl\nمَا كَانَ لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءٖۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ٣٨\n﴿ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى ٱلنَّاسِ﴾ أي: هذا من أفضل مننه وإحسانه وفضله علينا، وعلى من هداه الله كما هدانا؛ فإنه لا أفضل من منة الله على العباد بالإسلام والدين القويم، فمن قبله وانقاد له فهو حظه، وقد حصل له أكبر النعم وأجل الفضائل. السعدي: ٣٩٨.\nما أعظم نعم الله عليك؟\nمَا كَانَ لَنَآ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَيۡءٖۚ ذَٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا وَعَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ٣٨\nهذا التوحيد -وهو الإقرار بأنه لا إله إلا هو وحده لا شريك له- ﴿مِن فَضۡلِ ٱللَّهِ عَلَيۡنَا﴾ أي: أوحاه إلينا، وأمرنا به، ﴿وَعَلَى ٱلنَّاسِ﴾ إذ جعلنا دعاة لهم إلى ذلك، ﴿وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ﴾ أي: لا يعرفون نعمة الله عليهم بإرسال الرسل إليهم. ابن كثير:٢/٤٦٠.\nماذا يوحي إليك الإخبار بأن أكثر الناس لا يشكرون؟\nوَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ٣٨\n﴿وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ﴾: على نعمه بالتوحيد والإيمان. القرطبي:١١/٣٤٩.\nما النعمة الجليلة التي يقل شكر الناس لها؟\nإِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٤٠\nالحكم لله وحده، ورسله يبلغون عنه؛ فحكمهم حكمه، وأمرهم أمره، وطاعتهم طاعته؛ فما حكم به الرسول وأمرهم به وشرعه من الدين وجب على جميع الخلائق اتباعه وطاعته؛ فإن ذلك هو حكم الله على خلقه. ابن تيمية:٤/٤٣.\nحكم الرسول هو حكم لله تعالى، بين ذلك من الآية الكريمة.\nيَٰصَٰحِبَيِ ٱلسِّجۡنِ أَمَّآ أَحَدُكُمَا فَيَسۡقِي رَبَّهُۥ خَمۡرٗاۖ\nولكنه لم يعينه لئلَّا يحزن ذاك؛ ولهذا أبهمه. ابن كثير:٢/٤٦١.\nلِمَ لَم يُعَيِّن يوسف -عليه السلام- من الذي يسقي ربه خمرًا، ومن الذي يصلب؟\nوَقَالَ لِلَّذِي ظَنَّ أَنَّهُۥ نَاجٖ مِّنۡهُمَا ٱذۡكُرۡنِي عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيۡطَٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ ٤٢\n﴿فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ﴾:... لمَّا أراد الله أن يتم أمره، ويأذن بإخراج يوسف من السجن؛ قدَّر لذلك سببًا لإخراج يوسف وارتفاع شأنه وإعلاء قدره، وهو رؤيا الملك. السعدي: ٣٩٨.\nبيّن حكمة الله في قضائه وقدره من خلال الآية.\nوَقَالَ لِلَّذِي ظَنَّ أَنَّهُۥ نَاجٖ مِّنۡهُمَا ٱذۡكُرۡنِي عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّيۡطَٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِي ٱلسِّجۡنِ بِضۡعَ سِنِينَ ٤٢\nمن وقع في مكروه وشدة؛ لا بأس أن يستعين بمن له قدرة على تخليصه، أو الإخبار بحاله، وأن هذا لا يكون شكوى للمخلوق، فإن هذا من الأمور العادية التي جرى العرف باستعانة الناس بعضهم ببعض، ولهذا قال يوسف للذي ظن أنه ناج من الفتيين: ﴿ٱذۡكُرۡنِي عِندَ رَبِّكَ﴾. السعدي:٤١٠.\nهل الاستعانة بالمخلوقين فيما يقدرون عليه تنافي قوة الإيمان؟"],[241,"§يوسف\nwords\nأَضغَاثُأَخلاطُ.\nأُمَّةٍبَعدَ مُدَّةٍ.\nدَأَبًامُتَتَابِعَةً، وَأَنتُم جَادُّونَ في العَمَل.\nتُحصِنُونَتَحفَظُونَ، وَتَدَّخِرُونَ.\nيَعصرونيَعصِرُونَ الثِّمَارَ، لِكَثرَةِ الخِصبِ.\nحَاشَ لِلهِتَنزِيهًا لِلهِ.\nحَصحَصَ الحَقّظَهَرَ بَعدَ خَفَائِهِ.\ndeeds\nاسأل عالمًا عن أسئلة الناس التي يسألونك إياها.\nسل الله تعالى أن يعلمك، ويفتح عليك، كما فتح على نبي الله تعالى يوسف -عليه السلام-.\nاستخدم الذكاء والحيلة المباحة للوصول إلى حقك الذي صعُبَ عليك.\nguid\nعاقبة التقوى خير، وعاقبة المعاصي والفواحش الفضيحة.\nفضل العلم وشرفه؛ إذ به رفع الملك يوسف إلى حضرته.\nلا بد أن يظهر الحق ولو بعد حين.\nrefl\nيُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ\nووصفه بالمبالغة في الصِّدق حسبما علمه وجرَّبَ أحواله في مدة إقامته معه في السجن... وفيه إشارة إلى أنه ينبغي للمستفتي أن يعظم المفتي. الألوسي:١٢/٦٠٤.\nاذكر بعض آداب سؤال المفتي والعالِم.\nيُوسُفُ أَيُّهَا ٱلصِّدِّيقُ أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٖ سِمَانٖ يَأۡكُلُهُنَّ سَبۡعٌ عِجَافٞ\nعلم التعبير من العلوم الشرعية، وأنه يثاب الإنسان على تعلمه وتعليمه، وأن تعبير المرائي داخل في الفتوى؛ لقوله للفتيين: ﴿قُضِيَ ٱلۡأَمۡرُ ٱلَّذِي فِيهِ تَسۡتَفۡتِيَانِ﴾، وقال الملك: (أفتوني في رؤياي)، وقال الفتى ليوسف: ﴿أَفۡتِنَا فِي سَبۡعِ بَقَرَٰتٍ﴾؛ فلا يجوز الإقدام على تعبير الرؤيا من غير علم. السعدي:٤١٠.\nما منزلة تعبير الرؤيا من الشرع؟ وما دليلك على ما تقول؟\nقَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ ٤٧\nذكر له يوسف -عليه السلام- تعبيرها من غير تعنيف للفتى في نسيانه ما وصاه به، ومن غير اشتراط للخروج قبل ذلك. ابن كثير:٢/٤٦٢.\nهذا الموقف دَلَّ على تمام خُلُقِ يوسف -عليه السلام- وعقله، وضح ذلك.\nقَالَ تَزۡرَعُونَ سَبۡعَ سِنِينَ دَأَبٗا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِي سُنۢبُلِهِۦٓ إِلَّا قَلِيلٗا مِّمَّا تَأۡكُلُونَ ٤٧ ثُمَّ يَأۡتِي مِنۢ بَعۡدِ ذَٰلِكَ سَبۡعٞ شِدَادٞ يَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِيلٗا مِّمَّا تُحۡصِنُونَ ٤٨\nوقد مزج تعبيره بإرشاد جليل لأحوال التموين والادخار لمصلحة الأمة. ابن عاشور:١٢/٢٨٦.\nمزج يوسف -عليه السلام- تعبيره للرؤيا بالإرشاد، بين ذلك.\nوَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ ٥٠\nلم يذكر امرأة العزيز رعيًا لذمام زوجها، وسترًا لها؛ بل ذكر النسوة اللاتي قطعن أيديهنّ. ابن جزي:١/٤١٨.\nفي طلب يوسف سؤال النسوة قبل خروجه دلالة على حكمته وحلمه، كيف ذلك؟\nوَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ فَلَمَّا جَآءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّٰتِي قَطَّعۡنَ أَيۡدِيَهُنَّۚ إِنَّ رَبِّي بِكَيۡدِهِنَّ عَلِيمٞ ٥٠\nقال ابن عطية:... خشي أن يخرج وينال من الملك مرتبة، ويسكت عن أمر ذنبه صفحًا؛ فيراه الناس بتلك العين أبدًا، ويقولون: هذا الذي راود امرأة مولاه، فأراد يوسف -عليه السلام- أن يبين براءته، ويحقق منزلته من العفة والخير، وحينئذ يخرج للإحظاء والمنزلة؛ فلهذا قال للرسول: ارجع إلى ربك، وقل له: ما بال النسوة. القرطبي، ١١/٣٧٢.\nبيّن وجه الحكمة والأناة في طلب يوسف -عليه السلام- إعادة التحقيق في قضيته.\nوَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦۖ\nفضيلة العلم؛ علم الأحكام والشرع، وعلم تعبير الرؤيا، وعلم التدبير والتربية، وأنه أفضل من الصورة الظاهرة، ولو بلغت في الحسن جمال يوسف؛ فإن يوسف بسبب جماله حصلت له تلك المحنة والسجن، وبسبب علمه حصل له العز والرفعة والتمكين في الأرض؛ فإن كل خير في الدنيا والآخرة من آثار العلم وموجباته. السعدي:٤١٠.\nمن خلال قصة يوسف؛ قارن بين العلم و جمال الهيئة."],[242,"§يوسف\nwords\nلأَمَّارَةٌ بِالسُّوءِكَثِيرَةُ الأَمرِ بِالمَعَاصِي.\nأَستَخلِصهُأَجعَلهُ مِن خُلَصَائِي، وَأَهلِ مَشُورَتِي.\nمَكِينٌعَظِيمُ المَكَانَةِ.\nيَتَبَوَّأُيَنزِلُ.\nجَهَّزَهُمبِجَهَازِهِم أَعطَاهُم مَا طَلَبُوا، وَوَفَّى الكَيلَ لَهُم.\nسَنُرَاوِدُ عَنهُ أَبَاهُسَنَبذُلُ جُهدَنَا، لِإِقنَاعِ أَبِيهِ.\nرِحَالِهِمأَمتِعَتِهِم، وَأَوعِيَتِهِم.\ndeeds\nاستعذ بالله تعالى من شر نفسك، وشر الشيطان وشركه.\nتذكر قضية وقعت لك ثم حدد أخطاءك فيها واستغفر الله منها.\nأحسن إلى أحد إخوانك أو أقاربك.\nguid\nالاعتراف بالذنب من أسباب مغفرته، ومن علامات صدق التوبة والإنابة.\nينبغي إنصاف المظلوم ونصرته، وتقريب الصادق الأمين ولو كان ضعيفًا أو غريبًا.\nبالصبر تأتي العزة بعد المهانة والظلم.\nrefl\nوَمَآ أُبَرِّئُ نَفۡسِيٓۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّيٓۚ إِنَّ رَبِّي غَفُورٞ رَّحِيمٞ ٥٣\nويقال: النفوس ثلاثة أنواع، وهي: ﴿ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوٓءِ﴾: التي يغلب عليها اتباع هواها بفعل الذنوب والمعاصي، و(النفس اللوامة): وهي التي تذنب وتتوب؛ فعندها خير وشر، لكن إذا فعلت الشر تابت وأنابت، فتسمى لوامة؛ لأنها تلوم صاحبها على الذنوب، ولأنها تتلوم؛ أي: تتردد بين الخير والشر، و﴿ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ﴾: وهي التي تحب الخير والحسنات وتريده، وتبغض الشر والسيئات، وتكره ذلك، وقد صار ذلك لها خلقًا وعادةً وملكةً. ابن تيمية:٤/٤٥.\nما أنواع النفوس؟\nوَقَالَ ٱلۡمَلِكُ ٱئۡتُونِي بِهِۦٓ أَسۡتَخۡلِصۡهُ لِنَفۡسِيۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينٞ ٥٤\nوترتُّب هذا القول على تكليمه إياه دالّ على أن يوسف -عليه السلام- كلّم الملك كلامَ حكيمٍ أديبٍ؛ فلما رأى حسن منطقه، وبلاغة قوله، وأصالة رأيه؛ رآه أهلًا لثقته وتقريبه منه. ابن عاشور:١٣/٧.\nما سبب قول الملك ليوسف -عليه السلام- ﴿إِنَّكَ ٱلۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَمِينٌ﴾؟\nقَالَ ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمٞ ٥٥\nوأما سؤال الولاية فقد ذمه، وأمَّا سؤال يوسف وقوله: ﴿ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ﴾؛ فلأنه كان طريقًا إلى أن يدعوهم إلى الله، ويعدل بين الناس، ويرفع عنهم الظلم، ويفعل من الخير ما لم يكونوا [يفعلونه]؛ مع أنهم لم يكونوا يعرفون حاله، وقد علم بتعبير الرؤيا ما يؤول إليه حال الناس، ففي هذه الأحوال ونحوها ما يوجب الفرق بين مثل هذه الحال وبين ما نُهيَ عنه. ابن تيمية:٤/٥٥-٥٦.\nكيف سأل يوسف -عليه السلام- الولاية مع أن سؤال الولاية مذموم؟\nقَالَ ٱجۡعَلۡنِي عَلَىٰ خَزَآئِنِ ٱلۡأَرۡضِۖ إِنِّي حَفِيظٌ عَلِيمٞ ٥٥\nودلت الآية أيضًا على أنه يجوز للإنسان أن يصف نفسه بما فيه من علم وفضل، قال الماوردي: \"وليس هذا على الإطلاق في عموم الصفات، ولكنه مخصوص فيما اقترن بوصلة أو تعلَّق بظاهر من مكسب، وممنوع منه فيما سواه؛ لما فيه من تزكية ومراءاة، ولو تنزَّه الفاضل عنه لكان أليق بفضله؛ فإن يوسف دعته الضرورة إليه لما سبق من حاله، ولما يرجو من الظفر بأهله\". القرطبي:١١/٣٨٦.\nهل يجوز للإنسان أن يمدح نفسه ويثني عليها؟\nوَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ يَتَبَوَّأُ مِنۡهَا حَيۡثُ يَشَآءُۚ نُصِيبُ بِرَحۡمَتِنَا مَن نَّشَآءُۖ وَلَا نُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ٥٦\n﴿وَلَا نُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ﴾... وقال ابن عباس ووهب: يعني: الصابرين؛ لصبره في الجب، وفي الرق، وفي السجن، وصبره عن محارم الله عما دعته إليه المرأة. القرطبي:١١/٣٩٠.\nما أنواع الصبر التي صبرها يوسف -عليه السلام-؟\nوَلَأَجۡرُ ٱلۡأٓخِرَةِ خَيۡرٞ لِّلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ٥٧\nفبالتقوى تترك الأمور المحرمة من كبائر الذنوب وصغائرها، وبالإيمان التام يحصل تصديق القلب بما أمر الله بالتصديق به، وتتبعه أعمال القلوب، وأعمال الجوارح من الواجبات والمستحبات. السعدي:٤٠١.\nما أهمية التقوى والإيمان للوصول إلى الدار الآخرة؟\nوَقَالَ لِفِتۡيَٰنِهِ ٱجۡعَلُواْ بِضَٰعَتَهُمۡ فِي رِحَالِهِمۡ لَعَلَّهُمۡ يَعۡرِفُونَهَآ إِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمۡ لَعَلَّهُمۡ يَرۡجِعُونَ ٦٢\nقيل: أراد أن يريهم كرمه في رد البضاعة، وتقديم الضمان في البر والإحسان؛ ليكون أدعى لهم إلى العود. ﴿لَعَلَّهُمۡ يَعۡرِفُونَهَآ﴾ أي: كرامتهم علينا. البغوي:٢/٤٧٥.\nبيّن كرم يوسف -عليه السلام- لإخوته، وحرصه على رؤيتهم."],[243,"§يوسف\nwords\nمَا نَبغِيمَاذَا نَطلُبُ أَكثَرَ مِن هَذَا؟\nوَنَمِيرُنَجلِبُ طَعَامًا وَفِيرًا.\nكَيلَ بَعِيرٍحِملَ بَعِيرٍ.\nآوَىضَمَّ.\nفلا تَبتَئِسفَلاَ تَغتَمَّ.\ndeeds\nحافظ على الأذكار الشرعية كاملة بعد الصلوات؛ فهي وقاية من العين والسحر.\nانظر أخًا لك محتاجًا، وساعده.\nاكتب صفات يوسف -عليه السلام- وخطواته في حل مشكلته مع إخوته، واستفد منها في حل مشكلةٍ من مشاكلك الكبيرة.\nguid\nالعاقل يحذر من العين والحسد، ويعمل بالأسباب من غير مبالغة.\nاجتهد في فعل الأسباب، ولا تتوكل عليها، وتوكل على الله؛ فبيده الأمر كله.\nأطع والديك، وشاورهما واستأذنهما؛ فالخير فيما يأمران به.\nrefl\nقَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَمَآ أَمِنتُكُمۡ عَلَىٰٓ أَخِيهِ مِن قَبۡلُ فَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ ٦٤\nسوء الظن مع وجود القرائن الدالة عليه غير ممنوع ولا محرم. السعدي:٤١١.\nمتى يكون سوء الظن محرمًا؟\nفَٱللَّهُ خَيۡرٌ حَٰفِظٗاۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ ٦٤\nيقول: حفظه خير من حفظكم، وهو أرحم الراحمين. البغوي:٢/٤٧٦.\nبيّن كيف كان يقين يعقوب -عليه السلام- بالله تعالى.\nوَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ\nفيها دليل على التحرز من العين، والعين حق؛ وقد قال رسول الله -صلى الله عليه وسلم-: «إن العين لتدخل الرجل القبر، والجمل القدر»، وفي تعوذه -عليه السلام-: «أعوذ بكلمات الله التامة من كل شيطان وهامة، ومن كل عين لامَّة» ما يدل على ذلك. القرطبي:١١/٣٩٩.\nكيف يتحرز المؤمن من العين؟\nوَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ\nدلت الآية على أن المسلم يجب عليه أن يُحذِّرَ أخاه مما يخاف عليه، ويرشده إلى ما فيه طريق السلامة والنجاة؛ فإن الدين النصيحة، والمسلم أخو المسلم. القرطبي:١١/٤٠٣.\nماذا يجب عليك إذا خشيت على أخيك المسلم الضرر؟\nوَقَالَ يَٰبَنِيَّ لَا تَدۡخُلُواْ مِنۢ بَابٖ وَٰحِدٖ وَٱدۡخُلُواْ مِنۡ أَبۡوَٰبٖ مُّتَفَرِّقَةٖۖ وَمَآ أُغۡنِي عَنكُم مِّنَ ٱللَّهِ مِن شَيۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ٦٧\nوأراد بهذا تعليمهم الاعتماد على توفيق الله ولطفه، مع الأخذ بالأسباب المعتادة الظاهرة؛ تأدبًا مع واضع الأسباب ومقدّر الألطاف. ابن عاشور:١٣/٢١.\nهل فعل الأسباب ينافي التوكل على الله؟ وضح ذلك من خلال الآية الكريمة.\nمَّا كَانَ يُغۡنِي عَنۡهُم مِّنَ ٱللَّهِ مِن شَيۡءٍ إِلَّا حَاجَةٗ فِي نَفۡسِ يَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ\nوهو موجب الشفقة والمحبة للأولاد؛ فحصل له في ذلك نوع طمأنينة وقضاء لما في خاطره، وليس هذا قصورًا في علمه؛ فإنه من الرسل الكرام والعلماء الربانيين، ولهذا قال عنه: ﴿وَإِنَّهُۥ لَذُو عِلۡمٍ﴾ أي: صاحب علم عظيم. السعدي:٤٠٢.\nبَعد أن بَيَّن الله سبحانه أن تدبير يعقوب لا يغني شيئًا، قال: ﴿وَإِنَّهُۥ لَذُو عِلۡمٍ﴾، فما وجه هذه المقولة هنا؟\nوَإِنَّهُۥ لَذُو عِلۡمٖ لِّمَا عَلَّمۡنَٰهُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٦٨\n﴿لَذُو عِلۡمٍ﴾ يعني: كان يعمل ما يعمل عن علم لا عن جهل، ﴿لِّمَا عَلَّمۡنَٰهُ﴾ أي: لتعليمنا إياه. وقيل: إنه لعامل بما علم. قال سفيان: \"من لا يعمل بما يعلم لا يكون عالمًا\". البغوي:٢/٥٠٣.\nمتى يصح أن يقال للمرء إنه عالم؟"],[244,"§يوسف\nwords\nالعِيرُالقَافِلَةُ فِيهَا الأَحمَالُ.\nصُوَاعَصَاعَ.\nزَعِيمٌضَامِنٌ، وَكَافِلٌ.\nدِينِ المَلِكِحُكمِهِ وَقَضَائِهِ؛ لأِنَّهُ لَيسَ فِيهِ استِعبَادُ السَّارِقِ.\ndeeds\nاقرأ قصة يوسف -عليه السلام- من أحد كتب التفسير لتزداد بها علمًا.\nسل الله تعالى والتجئ إليه، وافتقر بين يديه أن يرزقك العلم والفهم.\nدرب نفسك اليوم على كظم الغيظ قدر ما تستطيع.\nguid\nبيان حسن تدبير الله تعالى لأوليائه.\nإذا أحب الله عبدًا رزقه الفهم والعلم.\nمعرفة العبد أن الله تعالى عالم بالعباد؛ بكيدهم ومكرهم وما يصفون، يهون عليه كلام الناس، ويعتز ويستغني بالله تعالى.\nrefl\nفَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ ٧٠\nجواز استعمال المكايد التي يتوصل بها إلى الحقوق، وأن العلم بالطرق الخفية الموصلة إلى مقاصدها مما يحمد عليه العبد، وإنَّما الممنوع التحيل على إسقاط واجب، أو فعل محرم. السعدي:٤١١.\nمن خلال هذه الآية؛ ما الحيل الجائزة؟ وما الحيل المحرمة؟\nفَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَايَةَ فِي رَحۡلِ أَخِيهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا ٱلۡعِيرُ إِنَّكُمۡ لَسَٰرِقُونَ ٧٠\nذكروا في تسميتهم سارقين وجهين؛ أحدهما: أنه من باب المعاريض، وأن يوسف نوى بذلك أنهم سرقوه من أبيه؛ حيث غيبوه عنه بالحيلة التي احتالوها عليه، وخانوه فيه، والخائن يسمى سارقًا؛ وهو من الكلام المشهور؛ حتى أن الخونة من ذوي الديوان يسمون لصوصًا. الثاني: أن المنادي هو الذي قال ذلك من غير أمر يوسف -عليه السلام-. ابن تيمية:٤/٥٧.\nكيف وُصِفَ إخوة يوسف بأنهم سارقون مع أنهم لم يسرقوا حقيقة؟\nكَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ فِي دِينِ ٱلۡمَلِكِ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ\nفحينئذ تم ليوسف ما أراد من بقاء أخيه عنده، على وجه لا يشعر به إخوته، قال تعالى: ﴿كَذَٰلِكَ كِدۡنَا لِيُوسُفَۖ﴾ أي: يسرنا له هذا الكيد، الذي توصل به إلى أمر غير مذموم. السعدي:٤٠٢.\nإذا أراد الله خيرًا بأوليائه فلا راد لقضائه، وضح ذلك من الآية.\nنَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ ٧٦\nيعني: الرفعة بالعلم؛ بدليل ما بعده ﴿وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٌ﴾ أي: فوق كل عالم من هو أعلم منه من البشر، أو الله -عز وجل-. ابن جزي:١/٤٢٢.\nلمَ فسرت الدرجات في هذه الآية بالعلم؟\nنَرۡفَعُ دَرَجَٰتٖ مَّن نَّشَآءُۗ\nأي: بالعلم والإيمان. القرطبي:١١/٤١٧.\nما الأمور التي يرتفع بها العبد درجات عالية؟\nوَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ ٧٦\nقال ابن عباس -رضي الله عنهما-: \"فوق كل عالم عالمٌ؛ إلى أن ينتهي العلم إلى الله تعالى\"؛ فالله تعالى فوق كل عالم. البغوي:٢/٤٨١.\nبيّن سعة علم الله -سبحانه وتعالى-.\nقَالُوٓاْ إِن يَسۡرِقۡ فَقَدۡ سَرَقَ أَخٞ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا يُوسُفُ فِي نَفۡسِهِۦ وَلَمۡ يُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرّٞ مَّكَانٗاۖ وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ ٧٧\n﴿وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ﴾ أي: الله أعلم أن ما قلتم كذب... وقد قيل: إن إخوة يوسف في ذلك الوقت ما كانوا أنبياء. القرطبي:٩/٢٢٨.\nكيف نسب إلى أخوة يوسف الكذب وقد قيل إنهم أنبياء؟"],[245,"§يوسف\nwords\nاستَيأَسُوايَئِسُوا وَانقَطَعَ رَجَاؤُهُم.\nخَلَصُوا نَجِيًّاانفَرَدُوا يَتَشَاوَرُونَ.\nأَبرَحَأُفَارِقَ.\nكَظِيمٌشَدِيدُ الكِتمَانِ لِحُزنِهِ.\nتَفتَأُمَا تَزَالُ.\ndeeds\nتأمل معاني أسماء الله الحسنى التي وردت في كلام يعقوب -عليه السلام- في القصة، و كيف كانت سببا في ثباته.\nاحرص اليوم على دعاء الخروج من المنزل -وفيه الاستعاذة من الظلم- وقل: \"اللهم إني أعوذ بك أن أَضِل أو أُضل، أو أزل أو أُزل، أو أظلم أو أُظلم، أو أجهل أو يجهل علي\".\nذكر، وانصح، وتعاهد إخوانك بالخير، كما فعل كبير إخوة يوسف مع إخوته.\nguid\nالجأ إلى الله أولًا قبل أن تلجأ إلى غيره؛ خاصة عند الشدائد.\nالبكاء أو الحزن عند وجود المصائب لا ينافي اليقين والثبات.\nمشاعر الحب والشوق للولد ليست منافيةً للإيمان، وليست عيبًا أو نقصًا في الرجال، ولكن قد تكون محلًّا للابتلاء.\nrefl\nقَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَٰعَنَا عِندَهُۥٓ\nينبغي لمن أراد أن يوهم غيره بأمر لا يحب أن يطلع عليه أن يستعمل المعاريض القولية والفعلية المانعة له من الكذب؛ كما فعل يوسف؛ حيث ألقى الصُّواع في رحل أخيه، ثم استخرجها منه موهمًا أنه سارق، وليس فيه إلا القرينة الموهمة لإخوته، وقال بعد ذلك: ﴿مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَٰعَنَا عِندَهُۥٓ﴾ ولم يقل: \"من سرق متاعنا\". السعدي:٤١١.\nكيف تخلص يوسف -عليه السلام- من الكذب عندما أراد أن يأخذ أخاه؟\nوَمَا شَهِدۡنَآ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَيۡبِ حَٰفِظِينَ ٨١\nتضمنت هذه الآية جواز الشهادة بأي وجه يحصل العلم بها؛ فإن الشهادة مرتبطة بالعلم عقلًا وشرعًا، فلا تسمع إلا ممن علم. القرطبي:١١/٤٢٦.\nما تقول فيمن يشهد على أمور لا علم له بها، هل يصح ذلك؟\nفَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ\nذكر الله الصبر الجميل، والصفح الجميل، والهجر الجميل؛ فالصبر الجميل: الذي لا شكوى معه، والهجر الجميل: الذي لا أذى معه، والصفح الجميل: الذي لا عتاب معه. ابن تيمية:٤/٦٣-٦٤.\nما المقصود بالصبر الجميل، والصفح الجميل، والهجر الجميل؟\nفَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ ٨٣\nجرت سنته تعالى أن الشدة إذا تناهت يجعل وراءها فرجًا عظيمًا... كأنه -عليه السلام- لمَّا رأى اشتداد البلاء قوي رجاؤه بالفرج؛ فقال ما قال. الألوسي:١٣/٥١.\nقرب الفرج له علامة يدركها الربانيون، فما هي؟\nوَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ ٨٤\nواستدل بالآية على جواز التأسف والبكاء عند النوائب، ولعل الكف عن أمثال ذلك لا يدخل تحت التكليف؛ فإنه قلَّ من يملك نفسه عند الشدائد. وقد روى الشيخان من حديث أنس أنه -صلى الله عليه وسلم- بكى على ولده إبراهيم، وقال: «إن العين تدمع، والقلب يخشع، ولا نقول إلا ما يرضي ربنا، وإنا لفراقك يا إبراهيم لمحزونون». وإنَّما المنهي عنه ما يفعله الجهلة: من النياحة، ولطم الخدود والصدور، وشق الجيوب، وتمزيق الثياب. الألوسي:١٣/٥٣.\nما المستحب، وما الجائز، وما المحرم عند حصول المصائب؟\nقَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ٨٦\nإنَّما أشكو إلى الله لا إليكم، ولا إلى غيركم. والبث: أشدّ الحزن. ﴿وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ﴾ أي: أعلم من لطفه ورأفته ورحمته ما يوجب حسن ظنّي به، وقوة رجائي فيه. ابن جزي:١/٤٢٥.\nما الذي يقصده يعقوب -عليه السلام- بقوله: ﴿وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ﴾؟\nقَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ\nالشكوى إلى الله لا تنافي الصبر، وإنَّما الذي ينافيه الشكوى إلى المخلوقين. السعدي:٤١١.\nمتى تعتبر الشكوى منافيةً للصبر؟"],[246,"§يوسف\nwords\nوَلاَ تَيأَسُوالاَ تَقطَعُوا رَجَاءَكُم.\nبِبِضَاعَةٍ مُزجَاةٍثَمَنٍ رَدِيءٍ قَلِيلٍ.\nلاَ تَثرِيبَلا تَأنِيبَ.\nفَصَلَتِ العِيرُخَرَجَتِ القَافِلَةُ مِن أَرضِ مِصرَ.\nتُفَنِّدُونِتُسَفِّهُونِي.\ndeeds\nتذكر مصيبة حلت بالأمة، ثم قارنها بصفات القدرة لله تعالى؛ فستعيش بعدها متفائلًا.\nسل الله تعالى أن يرزقك التقوى والصبر؛ فهما طريق الإحسان.\nحدد مشكلة وقعت بينك وبين أحد أقاربك، واتخذ قرارًا بالعفو عنه ابتغاء وجه الله تعالى؛ حتى تكون قريبًا من رحمة الله تعالى.\nguid\nإياك واليأس من رحمة الله تعالى، وغفرانه لذنبك؛ فالله تعالى رحيم كريم.\nثلاث صفات جعلت العاقبة ليوسف -عليه السلام-: التقوى، الصبر، الإحسان.\nالعفو عن المخطئين من صفات الأنبياء؛ ولا تَكتَفِ بمجرد العفو عمن أخطأ في حقك، بل زِدهُ دعوةً تنفعه في الدنيا والآخرة.\nrefl\nيَٰبَنِيَّ ٱذۡهَبُواْ فَتَحَسَّسُواْ مِن يُوسُفَ وَأَخِيهِ وَلَا تَاْيۡـَٔسُواْ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ ٨٧\nالرجاء يوجب للعبد السعي والاجتهاد فيما رجاه، والإياس يوجب له التثاقل والتباطؤ. السعدي:٤٠٤.\nما فائدة حسن الظن بالله، وعدم اليأس من رحمته سبحانه؟\nإِنَّهُۥ لَا يَاْيۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَٰفِرُونَ ٨٧\nإنَّما جعل اليأس من صفة الكافر؛ لأن سببه تكذيب الربوبية، أو [جهلٌ] بصفات الله من: قدرته، وفضله، ورحمته. ابن جزي:١/٤٢٥.\nلم كان اليأس من صفات الكافرين؟\nفَلَمَّا دَخَلُواْ عَلَيۡهِ قَالُواْ يَٰٓأَيُّهَا ٱلۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَٰعَةٖ مُّزۡجَىٰةٖ فَأَوۡفِ لَنَا ٱلۡكَيۡلَ وَتَصَدَّقۡ عَلَيۡنَآۖ إِنَّ ٱللَّهَ يَجۡزِي ٱلۡمُتَصَدِّقِينَ ٨٨ قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِيُوسُفَ وَأَخِيهِ إِذۡ أَنتُمۡ جَٰهِلُونَ ٨٩\nلمَّا شكوا إليه رقَّ لهم وعرّفهم بنفسه. ابن جزي:١/٤٢٥.\nبيّن أثر الكلمة الطيبة في التأثير على النفوس، وتغيير المواقف.\nإِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ ٩٠\nأي: يتق الله، ويصبر على المصائب وعن المعاصي، ﴿فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ﴾ أي: الصابرين في بلائه، القائمين بطاعته. القرطبي:١١/٤٤٣.\nمتى يصل العبد إلى عز الدنيا والآخرة؟\nقَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ ٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ ٩٢\nأسقط حق نفسه بقوله: ﴿لَا تَثۡرِيبَ عَلَيۡكُمُ ٱلۡيَوۡمَۖ﴾، ثم دعا إلى الله أن يغفر لهم حقه. ابن جزي:١/٤٢٦.\nفي هذه الآية منهج عظيم وخلق رفيع من أخلاق الأنبياء، بيّنه.\nقَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ ٱلۡيَوۡمَۖ يَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّٰحِمِينَ ٩٢\nلا تعيير عليكم اليوم، ولا أذكر لكم ذنبكم بعد اليوم. البغوي:٢/٤٩٤.\nإلى أي حد بلغ عفو يوسف وصفحه عن إخوته؟\nٱذۡهَبُواْ بِقَمِيصِي هَٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِي يَأۡتِ بَصِيرٗا\nولما كان مبدأ الهمِّ الذي أصابه من القميص الذي جاؤوا عليه بدم كذب؛ عَيَّنَ هذا القميص مبدأً للسرور، دون غيره من آثاره -عليه السلام-؛ ليُدخِل السرور عليه من الجهة التي دخل عليه الهَمُّ منها. الألوسي:١٤/١٠٣.\nما وجه اختيار القميص دون غيره من آثار يوسف -عليه السلام-؟"],[247,"§يوسف\nwords\nآوَىضَمَّ.\nالعَرشِسَرِيرِ المُلكِ.\nوَخَرُّوا لَهُ سُجَّدًاحَيَّوهُ بِالسُّجُودِ؛ تَكرِيمًا، لاَ عِبَادَةً، وَهُوَ فِي شَرعِهِم جَائِزٌ.\nالبَدوِالبَادِيَةِ.\nنَزَغَأَفسَدَ.\ndeeds\nاطلب العفو ممن ظلمتهم بالقول أو بالفعل قدر استطاعتك، أو استغفر لهم.\nاستعذ بالله أن ينزغ الشيطان بينك وبين إخوانك.\nعدد بعض نعم الله تعالى عليك، ثم سل الله تعالى شكرها وتمامها.\nguid\nمن أسباب شكرك لله سبحانه تذكّر حالتك قبل حصول النعمة.\nالعبرة بموافقة الشريعة لا بالقلة والكثرة.\nعدم استجابة المدعوين أحيانًا يكون ابتلاءً واختبارًا من الله تعالى للداعية.\nrefl\nقَالُواْ يَٰٓأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَآ إِنَّا كُنَّا خَٰطِـِٔينَ ٩٧\nولما سألوه الاستغفار لذنوبهم عللوه بالاعتراف بالذنب؛ لأنَّ الاعتراف شرط التوبة. البقاعي:٤/٩٧.\nهل الاعتراف بالذنب من شروط التوبة النصوح؟\nقَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ٩٨\nأراد أن ينبههم إلى عظم الذنب، وعظمة الله تعالى، وأنه سيكرر الاستغفار لهم في أزمنة مستقبلة. ابن عاشور:١٣/٥٤.\nلماذا وعد يعقوب -عليه السلام- أبناءه بالاستغفار لهم في المستقبل؟\nوَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ\nإنَّما لم يقل أخرجني من الجب لوجهين؛ أحدهما: أن في ذكر الجب [خزيًا] لإخوته، وتعريفهم بما فعلوه؛ فترك ذكره توقيرًا لهم. والآخر: أنه خرج من الجب إلى الرق، ومن السجن إلى الملك، فالنعمة به أكثر. ابن جزي:١/٤٢٧.\nلمَ لم يذكر يوسف -عليه السلام- نعمة إخراجه من الجب في هذا المقام؟\nمِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓ\nوهذا من لطفه وحسن خطابه -عليه السلام-... فلم يقل: \"نزغ الشيطان إخوتي\"، بل كأن الذنب والجهل صدر من الطرفين. السعدي:٤٠٥.\nلم جعل النَّزغ من الشيطان حاصلٌ منه ومن إخوته، مع أنه حصل من إخوته فقط؟\nأَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ ١٠١\n(أنت وليِّي)أي: الأقرب إليَّ باطنًا وظاهرًا. ﴿فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ﴾ أي: لا وليَّ لي غيرك. والولي يفعل لمولاه الأصلح والأحسن، فأحسن بي في الآخرة أعظم ما أحسنت بي في الدنيا. البقاعي:٤/١٠٠.\nما الثمرة والفائدة من أن يكون العبدُ من أولياء الله سبحانه؟\nرَبِّ قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ ١٠١\n﴿تَوَفَّنِي مُسۡلِمًا﴾: لمَّا عدد النعم التي أنعم الله بها عليه؛ دعا أن الله يتم عليه النعم بالوفاة على الإسلام إذا حان أجله. ابن جزي:١/٤٢٧.\nحصول نعم الدنيا لا يشغل عن طلب نعم الآخرة، وضح ذلك من خلال الآية.\nتَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ ١٠١\nوقال الصديق: ﴿تَوَفَّنِي مُسۡلِمًا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾، والصحيح من القولين أنه لم يسأل الموت، ولم يتمنه؛ وإنَّما سأل أنه إذا مات يموت على الإسلام؛ فسأل الصفة لا الموصوف كما أمر الله بذلك. ابن تيمية:٤/٦٧.\nهل تمنى يوسف -عليه السلام- الموت؟ وضح ذلك."],[248,"§يوسف\nwords\nوَكَأَيِّن مِن آيَةٍكَثِيرٌ مِنَ الآيَاتِ.\nغَاشِيَةٌعَذَابٌ يَعُمُّهُم.\nبَغتَةًفَجأَةً.\nاستَيأَسَ الرُّسُلُيَئِسُوا مِن أَقوَامِهِم.\nوَظَنُّواأَيقَنُوا\nبَأسُنَاعَذَابُنَا.\ndeeds\nتفكّر في آية من آيات الله التي تمرُّ عليها في الصباح أو في المساء.\nقل: \"اللهم إني أعوذ أن أشرك بك شيئًا وأنا أعلم، وأستغفرك لما لا أعلم\".\nبعد قراءتك لسورة يوسف استخرج منها خمس فوائد تؤثر في حياتك.\nguid\nالداعية إلى الله لا يبتغي من وراء دعوته أجرًا دنيويًا، بل هو حريص على الأجر الأخروي.\nلا تكن غافلًا عن آيات الله تعالى المبثوثة في السماوات والأرض.\nالدعوة إلى الله على بصيرة فارق بين دعوة الأنبياء وأتباعهم ودعوة غيرهم.\nrefl\nوَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ ١٠٦\nيندرج فيهم كل مَن أقرَّ بالله تعالى وخالقيته مثلًا، وكان مرتكبًا ما يُعَدُّ شركًا كيفما كان، ومن أولئك: عبدة القبور، الناذرون لها، المعتقدون للنفع والضر ممن الله تعالى أعلم بحاله فيها. الألوسي:١٣/٨٤.\nكيف يجتمع عند الانسان إيمان وشرك؟\nوَمَا يُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ ١٠٦\nفهم مؤمنون بربوبيته، مشركون في عبادته؛ كما قال النبي لحصين الخزاعي: «يا حصين كم تعبد؟» قال: سبعة آلهة؛ ستة في الأرض وواحدًا في السماء. قال: «فمن الذي تعد لرغبتك ورهبتك؟» قال: الذي في السماء. قال: «أسلم حتى أعلمك كلمة ينفعك الله تعالى بها»؛ فأسلم، فقال: «قل: اللهم ألهمني رشدي، وقني شر نفسي». ابن تيمية:٤/٦٧.\nلا يكفي الإيمان بربوبية الله وأسمائه وصفاته حتى تؤمن بتوحيده؛ بالدعاء، والاستغاثة، والاستعانة؛ بين ذلك من خلال الآية.\nقُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ وَسُبۡحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ ١٠٨\nوفي الآية دلالة على أن أصحاب النبي والمؤمنين الذين آمنوا به مأمورون بأن يدعوا إلى الإيمان بما يستطيعون. ابن عاشور:١٣/٦٥.\nينبغي للمؤمن أن يدعو إلى الله تعالى قدر استطاعته، بين ذلك.\nقُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ وَسُبۡحَٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ ١٠٨\nقال عبد الله بن مسعود: \"من كان مستنًا فليستن بمن قد مات؛ فإن الحي لا تؤمن عليه الفتنة. أولئك أصحاب محمد: كانوا خير هذه الأمة، وأبرها قلوبًا، وأعمقها علمًا، وأقلها تكلفًا؛ قوم اختارهم الله لصحبة نبيه -صلى الله عليه وسلم-، وإقامة دينه؛ فاعرفوا لهم فضلهم، واتبعوهم في آثارهم، وتمسكوا بما استطعتم من أخلاقهم وسيرهم؛ فإنهم كانوا على الهدى المستقيم\". البغوي:٤/٢٨٣.\nمن أفضل من فهم سنة النبي وسار عليها؟\nوَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِم\nإن الله تعالى لم يوح إلى امرأة من بنات بني آدم وحي تشريع. ابن كثير:٣/٤٧٧.\nالفطرة تقتضي أنه ليس الذكر كالأنثى، وأن كلًّا منهما ميسرٌ لما خُلق له، بين ذلك.\nأَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۗ\nيدل على أنه تعالى يغضبُ ممن أعرضَ عن تدبر آياته. البقاعي:٤/١١٣.\nهل تدبر مآل الظالمين وعاقبتهم من المستحبات، أم من الواجبات المتحتمات على كل مؤمن؟\nلَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةٞ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ حَدِيثٗا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ ١١١\nوالهُدى الذي في القصص: العبر الباعثة على الإيمان والتقوى بمشاهدة ما جاء من الأدلة في أثناء القصص على أن المتصرف هو الله تعالى، وعلى أن التقوى هي أساس الخير في الدنيا والآخرة، وكذلك الرحمة؛ فإن في قصص أهل الفضل دلالة على رحمة الله لهم وعنايته بهم. ابن عاشور:١٣/٧٢.\nبيّن بعض فوائد القصص."],[249,"§الرعد\nwords\nرَوَاسِيَجِبَالًا تُثَبِّتُ الأَرضَ.\nيُغشِييُغَطِّي.\nقِطَعٌبِقَاعٌ مُختَلِفَةٌ.\nمُتَجَاوِرَاتٌيُجَاوِرُ بَعضُهَا بَعضًا؛ مِنهَا: طَيِّبَةٌ، وَمِنهَا: سَبِخَةٌ مَلِحَةٌ.\nوَنَخِيلٌ صِنوَانٌمُجتَمِعَةٌ فِي مَنبَتٍ وَاحِدٍ.\nالأَغلاَلُالسَّلاَسِلُ.\ndeeds\nسل الله تعالى أن يرزقك التفكر في آياته، واليقين في موعوده.\nعدد ثلاثًا من فوائد تسخير الشمس والقمر للعباد.\nكُل فاكهتين من نوعين مختلفين، ثم تأمَل اختلاف طعمهما مع كونهما من أرض واحدة، وسُقِيَا بماء واحد.\nguid\nأقبل على هذا القرآن، وتعلم علومه؛ فإنة الطريق إلى الحق.\nعلامة الحق الدليل الصحيح وليس كثرة الأتباع وقلتهم.\nإنَّما يتعظ بآيات الله تعالى من كان له عقل.\nrefl\nالٓمٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِۗ وَٱلَّذِيٓ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ ٱلۡحَقُّ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ ١\nوالمقصود من هذه السورة هذه الآية، وهي وصف المُنَزَّل بأنه الحقّ وإقامة الدليل عليه. البقاعي:٤/١١٨.\nما مقصود سورة الرعد، وموضوعها؟\nوَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلّٞ يَجۡرِي لِأَجَلٖ مُّسَمّٗىۚ\nوذكر الشمس والقمر؛ لأنهما أظهر الكواكب السيارة، التي هي أشرف وأعظم من الثوابت؛ فإذا كان قد سخر هذه، فلأن يدخل في التسخير سائر الكواكب بطريق الأولى والأحرى. ابن كثير:٢/٤٨١.\nلماذا خُصَّت الشمس والقمر بالذكر؟\nيُفَصِّلُ ٱلۡأٓيَٰتِ لَعَلَّكُم بِلِقَآءِ رَبِّكُمۡ تُوقِنُونَ ٢\nفإن كثرة الأدلة وبيانها ووضوحها من أسباب حصول اليقين في جميع الأمور الإلهية، خصوصًا في العقائد الكبار؛ كالبعث، والنشور، والإخراج من القبور. السعدي:٤١٢.\nكيف يستطيع الإنسان الوصول إلى العلم اليقيني في الأمور الاعتقادية؟\nوَهُوَ ٱلَّذِي مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِيهَا رَوَٰسِيَ وَأَنۡهَٰرٗاۖ وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوۡجَيۡنِ ٱثۡنَيۡنِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ٣\nفإن التفكر فيها يؤدي إلى الحكم بأن يكون كل من ذلك على هذا النمط الرائق والأسلوب اللائق لا بد له من مكوِّن قادر، حكيم، يفعل ما يشاء، ويحكم ما يريد. الألوسي:١٣/١٢٧.\nما فائدة التفكر في خلق الأرض والجبال والثمرات والليل والنهار؟\nوَفِي ٱلۡأَرۡضِ قِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ وَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ فِي ٱلۡأُكُلِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ٤\n(لآيات)... دلالات واضحات على أن ذلك كله فعلُ واحدٍ، مختار، عليم، قادر على ما يريد من ابتداء الخلق، ثم تنويعه بعد إبداعه؛ فهو قادر على إعادته بطريق الأولى. البقاعي:٤/١٢٥.\nكيف دلَّ إنبات النبات واختلافه وتنوعه على البعث بعد الموت للجزاء والحساب؟\nوَفِي ٱلۡأَرۡضِ قِطَعٞ مُّتَجَٰوِرَٰتٞ وَجَنَّٰتٞ مِّنۡ أَعۡنَٰبٖ وَزَرۡعٞ وَنَخِيلٞ صِنۡوَانٞ وَغَيۡرُ صِنۡوَانٖ يُسۡقَىٰ بِمَآءٖ وَٰحِدٖ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضٖ فِي ٱلۡأُكُلِۚ\nأي: قرى متدانيات، ترابها واحد، وماؤها واحد، وفيها زروع وجنات، ثم تتفاوت في الثمار والتمر؛ فيكون البعض حلوًا، والبعض حامضًا، والغصن الواحد من الشجرة؛ قد يختلف الثمر فيه من الصغر والكبر، واللون، والطعم، وإن انبسط الشمس والقمر على الجميع على نسق واحد. وفي هذا أدل دليل على وحدانيته. القرطبي:١٢/١٠.\nما العبرة والآية في كون الأرض قطعًا متجاورات؟\nوَإِن تَعۡجَبۡ فَعَجَبٞ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَٰبًا أَءِنَّا لَفِي خَلۡقٖ جَدِيدٍۗ\nأي: هذا بعيد في غاية الامتناع بزعمهم؛ أنهم بعد ما كانوا ترابًا أن الله يعيدهم، فإنهم من جهلهم قاسوا قدرة الخالق بقدرة المخلوق، فلما رأوا هذا ممتنعًا في قدرة المخلوق ظنوا أنه ممتنع على قدرة الخالق، ونسوا أن الله خلقهم أول مرة ولم يكونوا شيئًا. السعدي:٤١٣.\nقياس الخالق على المخلوق سببٌ لضلال المشركين، وضِّح ذلك من خلال هذه الآية."],[250,"§الرعد\nwords\nالمَثُلاتُعُقُوبَاتُ أَمثَالِهِم مِنَ المُكَذِّبِينَ.\nتَغِيضُ الأَرحَامُتَنقُصُهُ الأَرحَامُ؛ فَيَسقُطُ قَبلَ تَمَامِهِ.\nوَسَارِبٌمَن جَهَرَ بِأَعمَالِهِ.\nمُعَقِّبَاتٌمَلاَئِكَةٌ يَتَعَاقَبُونَ عَلَى الإِنسَانِ لِحِفظِهِ، وَإِحصَاءِ عَمَلِهِ.\ndeeds\nصلِّ مع الجماعة في المسجد؛ خاصة الفجر والعصر؛ لأن الملائكة يتعاقبون فيهما، ويشهدون لمن حضرهما.\nقل أذكار الصباح والمساء؛ فهي سبب لحفظ الله تعالى لك.\nسنة الله تعالى أن يعاقب المجتمع على الذنب إذا كثر فيه؛ اربط بين مصيبة وقعت على المجتمع وذنب انتشر فيه.\nguid\nمهمة الداعية هي تبليغ الدعوة، لا إدخال الهداية إلى قلوب الناس.\nبيان سنة عظيمة من سنن الله سبحانه: أن النعم لا تزول إلا بالمعاصي.\nإذا أردت أن تصلح أحوالك وتزيد نعم الله عليك في الدنيا والآخرة فعليك بالبدء بتغيير نفسك بإبعادها عن الذنوب والمعاصي وأهلها.\nrefl\nوَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ\nلا يزال خيره إليهم، وإحسانه وبره وعفوه نازلًا إلى العباد، وهم لا يزال شرهم وعصيانهم إليه صاعدًا؛ يعصونه فيدعوهم إلى بابه، ويجرمون فلا يحرمهم خيره وإحسانه، فإن تابوا إليه فهو حبيبهم؛ لأنه يحب التوابين، ويحب المتطهرين، وإن لم يتوبوا فهو طبيبهم؛ يبتليهم بالمصائب ليطهرهم على المعايب. السعدي:٤١٣-٤١٤.\nوَضِّح كيف يكون إحسان الله ومغفرته واصلين إلى العباد مع ظلمهم.\nوَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ وَإِنَّ رَبَّكَ لَشَدِيدُ ٱلۡعِقَابِ ٦\nأي: أنه تعالى ذو عفو وصفح وستر للناس، مع أنهم يظلمون ويخطئون بالليل والنهار، ثم قرن هذا الحكم بأنه شديد العقاب؛ ليعتدل الرجاء والخوف. ابن كثير:٣/٤٨٣.\nما الفائدة من ذكر مغفرته وشدة عقابه في سياق واحد؟\nلَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ\nقال مجاهد: \"ما من عبد إلا وله ملك موكل به؛ يحفظه في نومه ويقظته من الجن والإنس والهوام،... إلا شيء يأذن اللّه فيه فيصيبه\". قال كعب الأحبار: \"لولا أن اللّه -عزّ وجلّ- وكّل بكم ملائكة يذبون عنكم في مطعمكم ومشربكم وعوراتكم لتخطفتكم الجن\". البغوي:٢/٥١٥.\nبيّن ثمرة من ثمرات إيمان المسلم بالملائكة وأعمالها الموكلة بها.\nلَهُۥ مُعَقِّبَٰتٞ مِّنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ يَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ\nمن فوائد الحفظة للأعمال: أن العبد إذا علم أن الملائكة -عليهم السلام- يحضرونه، ويحصون عليه أعماله، وهم هم؛ كان أقرب إلى الحذر من ارتكاب المعاصي؛ كمن يكون بين يدي أناس أجلّاء من خُدَّام المَلِك، موكَّلِين عليه؛ فإنه لا يكاد يحاول معصية بينهم. الألوسي:١٣/١٤٣.\nإذا استشعر المرء وجود الملائكة معه فما أثر ذلك على سلوكه؟\nوَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٖ سُوٓءٗا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ ١١\n﴿وَإِذَآ أَرَادَ ٱللَّهُ بِقَوۡمٍ سُوٓءًا﴾ أي: عذابًا وهلاكًا. ﴿فَلَا مَرَدَّ لَهُۥۚ﴾ أي: لا راد له. ﴿وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ﴾ أي: ملجأ يلجؤون إليه. البغوي:٢/٥١٨.\nهل يستطيع أحد أن يفر من عذاب الله؟\nهُوَ ٱلَّذِي يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ ١٢ وَيُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ وَٱلۡمَلَٰٓئِكَةُ مِنۡ خِيفَتِهِۦ وَيُرۡسِلُ ٱلصَّوَٰعِقَ فَيُصِيبُ بِهَا مَن يَشَآءُ وَهُمۡ يُجَٰدِلُونَ فِي ٱللَّهِ وَهُوَ شَدِيدُ ٱلۡمِحَالِ ١٣\nفإذا كان هو وحده الذي يسوق للعباد الأمطار والسحب التي فيها مادة أرزاقهم، وهو الذي يدبر الأمور، وتخضع له المخلوقات العظام التي يُخافُ منها وتزعج العباد، وهو شديد القوة؛ فهو الذي يستحق أن يعبد وحده لا شريك له. السعدي:٤١٥.\nما الذي يفيده المسلم من إشفاق القوى الكونية المختلفة من الله -سبحانه وتعالى- وتصرفه فيها؟\nهُوَ ٱلَّذِي يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ ١٢\nخوفًا من الصاعقة، طمعًا في نفع المطر... وعن عبد الله بن الزبير أنه كان إذا سمع صوت الرعد ترك الحديث، وقال: \"سبحان من يسبح الرعد بحمده والملائكة من خيفته\"، ويقول: \"إن هذا الوعيد لأهل الأرض شديد\". البغوي:٢/٥١٨.\nبيِّن هدي السلف إذا سمعوا الرعد أو رأوا البرق."],[251,"§الرعد\nwords\nبِالغُدُوِّأَوَّلِ النَّهَارِ.\nوَالآصَالِآخِرِ النَّهَارِ.\nبِقَدَرِهَابِقَدرِ صِغَرِ الأودِيَةِ وَكِبَرِهَا.\nزَبَدًاغُثَاءً لا نَفعَ فِيهِ.\nرَابِيًامُرتَفِعًا.\nجُفَاءًمُتَلاشِيًا لاَ بَقَاءَ لَهُ، أَو يُرمَى بِهِ؛ إِذ لا فَائِدَةَ مِنهُ.\ndeeds\nخطط اليوم لعمل صالح -ولو يسير- يبقى لك بعد موتك.\nحدد أمرًا أمرك الله به من الآيات التي تتلوها، ونفذه استجابة لأمر الله تعالى.\nتصدَّق صدقة تطوع قبل أن يأتي يوم تتمنى أن تتصدق فيه ولا تستطيع.\nguid\nالقلوب كالأودية؛ متفاوتة في سعتها، وكل يأخذ من الخير بمقدار سعته.\nقاعدة لا تتبدل ولا تتغير: الحق يبقى وإن ظن الناس زواله واندثاره، والباطل يضمحل مهما انتفش وتضخم.\nضرب الأمثال وسيلة تعليمية وتربوية ناجعة استخدمها القرآن، واستخدمها النبي؛ فتدرب عليها.\nrefl\nوَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَسۡتَجِيبُونَ لَهُم بِشَيۡءٍ إِلَّا كَبَٰسِطِ كَفَّيۡهِ إِلَى ٱلۡمَآءِ لِيَبۡلُغَ فَاهُ وَمَا هُوَ بِبَٰلِغِهِۦۚ وَمَا دُعَآءُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ١٤\nالذي يدعو إلها من دون الله كالظمآن الذي يدعو الماء إلى فيه من بعيد؛ يريد تناوله ولا يقدر عليه بلسانه، ويشير إليه بيده فلا يأتيه أبدًا؛ لأن الماء لا يستجيب، وما الماء ببالغ إليه. القرطبي:١٢/٤٢-٤٣.\nبيّن معنى المثل الذي ضربه الله تعالى لحال المشرك.\nوَمَا دُعَآءُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ١٤\nلبطلان ما يدعون من دون الله؛ فبطلت عباداتهم ودعاؤهم؛ لأن الوسيلة تبطل ببطلان غايتها. السعدي:٤١٥.\nلماذا كان دعاء الكافرين في ضلال؟ وما علاقة الوسيلة بالغاية من حيث الصحة والبطلان؟\nوَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَظِلَٰلُهُم بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ۩ ١٥\nوسجود كل شيء بحسب حاله؛ كما قال تعالى: ﴿وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡ﴾ [الإسراء: ٤٤]. السعدي:٤١٥.\nكيف يسجد جميع من في السماوات والأرض؟\nوَلِلَّهِۤ يَسۡجُدُۤ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ طَوۡعٗا وَكَرۡهٗا وَظِلَٰلُهُم بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ۩ ١٥\nومن حكمة السجود عند قراءتها أن يضع المسلم نفسه في عداد ما يسجد لله طوعًا بإيقاعه السجود؛ وهذا اعتراف فعلي بالعبودية لله تعالى. ابن عاشور:١٣/١١٢.\nاذكر الحكمة من سجود التلاوة عند هذه الآية.\nأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَسَالَتۡ أَوۡدِيَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّيۡلُ زَبَدٗا رَّابِيٗاۖ وَمِمَّا يُوقِدُونَ عَلَيۡهِ فِي ٱلنَّارِ ٱبۡتِغَآءَ حِلۡيَةٍ أَوۡ مَتَٰعٖ زَبَدٞ مِّثۡلُهُۥۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَٰطِلَۚ\nفشبه العلم بالماء المنزل من السماء؛ لأن به حياة القلوب كما أن بالماء حياة الأبدان، وشبه القلوب بالأودية؛ لأنها محل العلم كما أن الأودية محل الماء؛ فقلب يسع علمًا كثيرًا، وواد يسع ماء كثيرًا، وقلب يسع علمًا قليلًا، وواد يسع ماء قليلًا. ابن تيمية:٤/٨٦.\nتختلف القلوب في احتوائها للعلم، بين ذلك من خلال الآية.\nفَأَمَّا ٱلزَّبَدُ فَيَذۡهَبُ جُفَآءٗۖ وَأَمَّا مَا يَنفَعُ ٱلنَّاسَ فَيَمۡكُثُ فِي ٱلۡأَرۡضِۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ ١٧\nضرب مثلًا للحق والباطل، فشبه الكفر بالزبد الذي يعلو الماء؛ فإنه يضمحل، ويعلق بجنبات الأودية، وتدفعه الرياح؛ فكذلك يذهب الكفر ويضمحل... وهذان المثلان ضربهما الله للحق في ثباته، والباطل في اضمحلاله؛ فالباطل -وإن علا في بعض الأحوال- فإنه يضمحل كاضمحلال الزبد والخبث. القرطبي:١٢/٤٨-٥١.\nكيف صور القرآن مآل الحق والباطل؟\nوَٱلَّذِينَ لَمۡ يَسۡتَجِيبُواْ لَهُۥ لَوۡ أَنَّ لَهُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦٓۚ أُوْلَٰٓئِكَ لَهُمۡ سُوٓءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ ١٨\nقال إبراهيم النخعي: ﴿سُوٓءُ ٱلۡحِسَابِ﴾ أي: يحاسب الرجل بذنبه كله؛ لا يغفر له [منه] شيء. البغوي:٢/٥٢٣.\nكيف يكون سوء الحساب يوم القيامة؟"],[252,"§الرعد\nwords\nالأَلبَابِالعُقُولِ.\nالمِيثَاقَالعَهدَ المُؤَكَّدَ.\nوَيَدرَأُونَ يَدفَعُونَ.\nعُقبى الدَّارِالعَاقِبَةُ المَحمُودَةُ فِي الآخِرَةِ.\nوَيَقدِرُيُضَيِّقُ.\nمَتَاعٌشَيءٌ قَلِيلٌ يُتَمَتَّعُ بِهِ سُرعَانَ مَا يَزُولُ.\ndeeds\nصِلْ أحد أقاربك بزيارته، أو الاتصال به.\nتصدق بصدقتين في سبيل الله: إحداها سرًّا، والثانية علانيةً.\nتذكر أحدًا أساء إليك، وأحسن إليه برسالة جوال طيبة، أو هدية محببة.\nguid\nالصبر قد يحصل من البر والفاجر، ولكن الصبر المأجور هو الذي يكون ابتغاء رضوان الله -سبحانه وتعالى-.\nليس كل ما يفرحك في الدنيا ينفعك في الآخرة.\nسعة الرزق وضيقه ليست دليلًا على رضى الله سبحانه أو سخطه على العبد.\nrefl\nإِنَّمَا يَتَذَكَّرُ أُوْلُواْ ٱلۡأَلۡبَٰبِ ١٩ ٱلَّذِينَ يُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا يَنقُضُونَ ٱلۡمِيثَٰقَ ٢٠\nأي: العهد الذي عاهدوا عليه الله؛ فدخل في ذلك جميع المواثيق والعهود والأَيمَان والنذور، فلا يكون العبد من أولي الألباب الذين لهم الثواب العظيم إلا بأدائها كاملة، وعدم نقضها وبخسها. السعدي:٤١٦.\nمتى يعتبر العبد من أولي الألباب؟\nوَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ ٢٢\nقيل: يدفعون من أساء إليهم بالتي هي أحسن، والأظهر: يفعلون الحسنات فيدرؤون بها السيئات؛ كقوله: ﴿إِنَّ ٱلۡحَسَنَٰتِ يُذۡهِبۡنَ ٱلسَّيِّـَٔاتِ﴾ [هود: ١١٤]. ابن جزي:١/٤٣٦.\nفتح الله لعباده بابًا يدفعون عنهم به السيئات، فما هو؟\nجَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۖ\nأي: يجمع بينهم وبين أحبابهم من الآباء والأهلين والأبناء -ممن هو صالح لدخول الجنة من المؤمنين-؛ لتقر أعينهم بهم. ابن كثير:٣/٤٩٢.\nلماذا جمع الله الآباء والأزواج والذرية الصالحة في الجنة؟\nوَٱلۡمَلَٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٖ ٢٣ سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ ٢٤\nثم زاد في الترغيب بقوله -سبحانه وتعالى-: ﴿وَٱلۡمَلَٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٍ﴾؛ لأن الإكثار من ترداد رسل الملك أعظم في الفخر، وأكثر في السرور والعز. البقاعي:٤/١٤٧.\nما فائدة دخول الملائكة على المؤمنين في الجنة؟\nٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا مَتَٰعٞ ٢٦\nسعة رزقهم ليس تكريمًا لهم، كما أن تضييق رزق بعض المؤمنين ليس لإهانة لهم؛ وإنَّما كل من الأمرين صادر منه تعالى لحِكَم إلهية يعلمها سبحانه، وربما وسع على الكافر إملاءً واستدراجًا له، وضيّق على المؤمن زيادة لأجره. الألوسي:١٣/١٨٤.\nهل زيادة الرزق في الدنيا دليل على توفيق المرء وكرامته؟\nوَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nفرحًا أوجب لهم أن يطمئنوا بها، ويغفلوا عن الآخرة؛ وذلك لنقصان عقولهم. السعدي:٤١٧.\nمتى يكون الفرح بأمور الدنيا مذمومًا؟\nٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَئِنُّ ٱلۡقُلُوبُ ٢٨\nكل قلب يطمئن به، فمن أخبر عن قلبه بخلاف ذلك فهو كاذب معاند، ومن أذعن وعمل بموجب الطمأنينة فهو مؤمن. البقاعي:٤/١٤٧.\nما الذي يمنع القلوب من تمام الطمأنينة؟"],[253,"§الرعد\nwords\nطُوبَى لَهُمفَرَجٌ، وَقُرَّةُ عَينٍ، وَحَالٌ طَيِّبَةٌ.\nقَارِعَةٌ مُصِيبَةٌ.\nفَأَملَيتُأَمهَلتُ.\nأَم بِظَاهِرٍ مِن القَولِأَي: تُسَمُّونَهُم شُرَكَاءَ فِي ظَاهِرِ القَولِ، مِن غَيرِ أَن يَكُونَ لَهُم حَقِيقَةٌ.\ndeeds\nسل الله تعالى العيش الطيب والعاقبة الحسنة.\nقل إذا أصبحت: \"حسبي الله لا إله إلا هو عليه توكلت، وهو رب العرش العظيم\".\nإذا خرجت من منزلك فقل: \"بسم الله توكلتُ على الله، لا حول ولا قوة إلا بالله\".\nguid\nإذا واجهتَ من يستهزئ بك بسبب إيمانك واستقامتك؛ فأعرض عن جهلهم، ولا تحزن، واعلم أن الله تعالى سينتصر لك، وأنَّ نبيك -صلى الله عليه وسلم- قد لقي أكثر من ذلك، فاصبر ابتغاء وجه الله تعالى.\nالمصائب قد تكون أحيانًا بسبب المعاصي؛ فتجنب المعاصي تهنأ في حياتك -بإذن الله-.\nاعلم أن المكذبين والظالمين والعصاة مهما فخروا وطغوا ورأى الناس أنهم في سعادة فهم في عذاب؛ كيف وقد توعدهم الله بعذاب في الحياة الدنيا.\nrefl\nوَهُمۡ يَكۡفُرُونَ بِٱلرَّحۡمَٰنِۚ\nوقوله: (بالرحمن) إشارة إلى كثرة حلمه، وطول أناته، وتصوير لتقبيح حالهم في مقابلتهم الإحسان بالإساءة، والنعمة بالكفر بأوضح صورة، وهم يدَّعون أنهم أشكر الناس للإحسان، وأبعدُهم من الكفران. البقاعي:٤/١٥١.\nفي ذكر اسم (الرحمن) دون غيره من أسماء الله الحسنى فائدة لطيفة، فما هي؟\nقُلۡ هُوَ رَبِّي لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ ٣٠\nفإن الإنابة إلى الله والمتاب هو الرجوع إليه بعبادته وطاعته وطاعة رسوله. والعبد لا يكون مطيعًا لله ورسوله -فضلًا أن يكون من خواص أوليائه المتقين- إلا بفعل ما أمر به، وترك ما نهى عنه. ابن تيمية:٤/٩٣.\nما المقصود بالإنابة إلى الله؟\nقُلۡ هُوَ رَبِّي لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ ٣٠\n﴿وَإِلَيۡهِ مَتَابِ﴾ أي: إليه توبتي؛ كقوله تعالى: ﴿وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ﴾ [محمد: ١٩]؛ أُمِرَ -عليه الصلاة والسلام- بذلك إبانة لفضل التوبة ومقدارها عند الله تعالى، وأنها صفة الأنبياء. الألوسي: ١٣/١٩٣.\nبينت الآية صفة من صفات الأنبياء -عليهم السلام-، فما هي؟\nأَفَلَمۡ يَاْيۡـَٔسِ ٱلَّذِينَ ءَامَنُوٓاْ أَن لَّوۡ يَشَآءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِيعٗاۗ\nأفلم يعلم الذين آمنوا أن لو يشاء الله لهدى الناس جميعًا من غير أن يشاهدوا الآيات؟! وقيل: إن الإياس على معناه الحقيقي؛ أي: أفلم ييأس الذين آمنوا من إيمان هؤلاء الكفار؟! لعلمهم أن الله تعالى لو أراد هدايتهم لهداهم؛ لأن المؤمنين تمنوا نزول الآيات التي اقترحها الكفار طمعًا في إيمانهم. الشوكاني:٣/١٠١.\nعلى الداعية البلاغ والإرشاد، والنتائج عائدة إلى علم الله وحكمته، وضح ذلك من الآية.\nوَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلٖ مِّن قَبۡلِكَ فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُواْ\nأي: أمهلتهم مدة؛ حتى ظنوا أنهم غير معذبين... فلا يغتر هؤلاء الذين كذبوك واستهزأوا بك بإمهالنا؛ فلهم أسوة فيمن قبلهم من الأمم، فليحذروا أن يفعل بهم كما فعل بأولئك. السعدي:٤١٨.\nما خطورة أمن الإنسان من العذاب وهو مقيم على المعاصي؟\nأَفَمَنۡ هُوَ قَآئِمٌ عَلَىٰ كُلِّ نَفۡسِۢ بِمَا كَسَبَتۡۗ\nهو الله تعالى؛ أي: حفيظ رقيب على عمل كل أحد. والخبر محذوف تقديره: أفمن هو قائم على كل نفس بما كسبت أحقُّ أن يعبد أم غيره؟! ابن جزي:١/ ٤٣٨.\nالقيومية لله تعالى تتضمن عدة معانٍ وصفات، بيّنها.\nوَجَعَلُواْ لِلَّهِ شُرَكَآءَ قُلۡ سَمُّوهُمۡۚ\n﴿قُلۡ سَمُّوهُمۡۚ﴾: بأسمائهم الحقيقية؛ فإنهم إذا سمّوهُم، وعُرِفت حقائقهم أنها حجارة أو غير ذلك مما هو مركز العجز ومحل الفقر؛ عُرِفَ ما هم عليه من سخافة العقول وركاكة الآراء. البقاعي:،٤/١٥٥.\nما فائدة الطلب من الكفار أن يذكروا أسماء أصنامهم؟"]])